window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["EST"]={"book":"EST","editions":{"hbo-source":[[1,1,"וַ⁠יְהִ֖י בִּ⁠ימֵ֣י אֲחַשְׁוֵר֑וֹשׁ ה֣וּא אֲחַשְׁוֵר֗וֹשׁ הַ⁠מֹּלֵךְ֙ מֵ⁠הֹ֣דּוּ וְ⁠עַד־כּ֔וּשׁ שֶׁ֛בַע וְ⁠עֶשְׂרִ֥ים וּ⁠מֵאָ֖ה מְדִינָֽה׃","wa⁠yĕhi֖y bi̇⁠ymé֣y ʼàẖaşĕ̌wér֑wòş̌ h֣ẇʼ ʼàẖaşĕ̌wér֗wòş̌ ha⁠mò̇lékĕ֙ mé⁠hò֣ḋẇ wĕ⁠ʻad-k̇֔ẇş̌ şě֛baʻ wĕ⁠ʻeşĕ̂ri֥ym ẇ⁠méʼá֖h mĕdiynáֽh׃"],[1,2,"בַּ⁠יָּמִ֖ים הָ⁠הֵ֑ם כְּ⁠שֶׁ֣בֶת ׀ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֗וֹשׁ עַ֚ל כִּסֵּ֣א מַלְכוּת֔⁠וֹ אֲשֶׁ֖ר בְּ⁠שׁוּשַׁ֥ן הַ⁠בִּירָֽה׃","bȧ⁠yá̇mi֖ym há⁠hé֑m kĕ̇⁠şě֣beţ ׀ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֗wòş̌ ʻa֚l ki̇sé֣̇ʼ malĕkẇţ֔⁠wò ʼàşě֖r bĕ̇⁠ş̌ẇşǎ֥n ha⁠bi̇yráֽh׃"],[1,3,"בִּ⁠שְׁנַ֤ת שָׁלוֹשׁ֙ לְ⁠מָלְכ֔⁠וֹ עָשָׂ֣ה מִשְׁתֶּ֔ה לְ⁠כָל־שָׂרָ֖י⁠ו וַ⁠עֲבָדָ֑י⁠ו חֵ֣יל ׀ פָּרַ֣ס וּ⁠מָדַ֗י הַֽ⁠פַּרְתְּמִ֛ים וְ⁠שָׂרֵ֥י הַ⁠מְּדִינ֖וֹת לְ⁠פָנָֽי⁠ו׃","bi̇⁠şĕ̌na֤ţ şá̌lwòş̌֙ lĕ⁠málĕk֔⁠wò ʻáşá֣̂h mişĕ̌ţė֔h lĕ⁠kál-şá̂rá֖y⁠w wa⁠ʻàbádá֑y⁠w ẖé֣yl ׀ pá̇ra֣s ẇ⁠máda֗y haֽ⁠pȧrĕţĕ̇mi֛ym wĕ⁠şá̂ré֥y ha⁠mĕ̇diyn֖wòţ lĕ⁠pánáֽy⁠w׃"],[1,4,"בְּ⁠הַרְאֹת֗⁠וֹ אֶת־עֹ֨שֶׁר֙ כְּב֣וֹד מַלְכוּת֔⁠וֹ וְ⁠אֶ֨ת־יְקָ֔ר תִּפְאֶ֖רֶת גְּדוּלָּת֑⁠וֹ יָמִ֣ים רַבִּ֔ים שְׁמוֹנִ֥ים וּ⁠מְאַ֖ת יֽוֹם׃","bĕ̇⁠harĕʼòţ֗⁠wò ʼeţ-ʻò֨şěr֙ kĕ̇b֣wòd malĕkẇţ֔⁠wò wĕ⁠ʼe֨ţ-yĕqá֔r ţi̇pĕʼe֖reţ gĕ̇dẇlá̇ţ֑⁠wò yámi֣ym rabi̇֔ym şĕ̌mwòni֥ym ẇ⁠mĕʼa֖ţ yֽwòm׃"],[1,5,"וּ⁠בִ⁠מְל֣וֹאת ׀ הַ⁠יָּמִ֣ים הָ⁠אֵ֗לֶּה עָשָׂ֣ה הַ⁠מֶּ֡לֶךְ לְ⁠כָל־הָ⁠עָ֣ם הַ⁠נִּמְצְאִים֩ בְּ⁠שׁוּשַׁ֨ן הַ⁠בִּירָ֜ה לְ⁠מִ⁠גָּ֧דוֹל וְ⁠עַד־קָטָ֛ן מִשְׁתֶּ֖ה שִׁבְעַ֣ת יָמִ֑ים בַּ⁠חֲצַ֕ר גִּנַּ֥ת בִּיתַ֖ן הַ⁠מֶּֽלֶךְ׃","ẇ⁠bi⁠mĕl֣wòʼţ ׀ ha⁠yá̇mi֣ym há⁠ʼé֗lėh ʻáşá֣̂h ha⁠mė֡lekĕ lĕ⁠kál-há⁠ʻá֣m ha⁠ni̇mĕẕĕʼiym֩ bĕ̇⁠ş̌ẇşǎ֨n ha⁠bi̇yrá֜h lĕ⁠mi⁠gá֧̇dwòl wĕ⁠ʻad-qátá֛n mişĕ̌ţė֖h şǐbĕʻa֣ţ yámi֑ym bȧ⁠ẖàẕa֕r gi̇nȧ֥ţ bi̇yţa֖n ha⁠mėֽlekĕ׃"],[1,6,"ח֣וּר ׀ כַּרְפַּ֣ס וּ⁠תְכֵ֗לֶת אָחוּז֙ בְּ⁠חַבְלֵי־ב֣וּץ וְ⁠אַרְגָּמָ֔ן עַל־גְּלִ֥ילֵי כֶ֖סֶף וְ⁠עַמּ֣וּדֵי שֵׁ֑שׁ מִטּ֣וֹת ׀ זָהָ֣ב וָ⁠כֶ֗סֶף עַ֛ל רִֽצְפַ֥ת בַּהַט־וָ⁠שֵׁ֖שׁ וְ⁠דַ֥ר וְ⁠סֹחָֽרֶת׃","ẖ֣ẇr ׀ kȧrĕpȧ֣s ẇ⁠ţĕké֗leţ ʼáẖẇz֙ bĕ̇⁠ẖabĕléy-b֣ẇẕ wĕ⁠ʼarĕgá̇má֔n ʻal-gĕ̇li֥yléy ke֖sep wĕ⁠ʻaṁ֣ẇdéy şé֑̌ş̌ miṫ֣wòţ ׀ záhá֣b wá⁠ke֗sep ʻa֛l riֽẕĕpa֥ţ bȧhat-wá⁠şé֖̌ş̌ wĕ⁠da֥r wĕ⁠sòẖáֽreţ׃"],[1,7,"וְ⁠הַשְׁקוֹת֙ בִּ⁠כְלֵ֣י זָהָ֔ב וְ⁠כֵלִ֖ים מִ⁠כֵּלִ֣ים שׁוֹנִ֑ים וְ⁠יֵ֥ין מַלְכ֛וּת רָ֖ב כְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wĕ⁠haşĕ̌qwòţ֙ bi̇⁠kĕlé֣y záhá֔b wĕ⁠kéli֖ym mi⁠ké̇li֣ym ş̌wòni֑ym wĕ⁠yé֥yn malĕk֛ẇţ rá֖b kĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[1,8,"וְ⁠הַ⁠שְּׁתִיָּ֥ה כַ⁠דָּ֖ת אֵ֣ין אֹנֵ֑ס כִּי־כֵ֣ן ׀ יִסַּ֣ד הַ⁠מֶּ֗לֶךְ עַ֚ל כָּל־רַ֣ב בֵּית֔⁠וֹ לַ⁠עֲשׂ֖וֹת כִּ⁠רְצ֥וֹן אִישׁ־וָ⁠אִֽישׁ׃","wĕ⁠ha⁠şĕ̇̌ţiyá֥̇h ka⁠dá֖̇ţ ʼé֣yn ʼòné֑s ki̇y-ké֣n ׀ yisȧ֣d ha⁠mė֗lekĕ ʻa֚l ká̇l-ra֣b bé̇yţ֔⁠wò la⁠ʻàş֖̂wòţ ki̇⁠rĕẕ֥wòn ʼiyş̌-wá⁠ʼiֽyş̌׃"],[1,9,"גַּ֚ם וַשְׁתִּ֣י הַ⁠מַּלְכָּ֔ה עָשְׂתָ֖ה מִשְׁתֵּ֣ה נָשִׁ֑ים בֵּ֚ית הַ⁠מַּלְכ֔וּת אֲשֶׁ֖ר לַ⁠מֶּ֥לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃ס","gȧ֚m waşĕ̌ţi֣̇y ha⁠mȧlĕká̇֔h ʻáşĕ̂ţá֖h mişĕ̌ţé֣̇h náşǐ֑ym bé֚̇yţ ha⁠mȧlĕk֔ẇţ ʼàşě֖r la⁠mė֥lekĕ ʼàẖaşĕ̌wérֽwòş̌׃s"],[1,10,"בַּ⁠יּוֹם֙ הַ⁠שְּׁבִיעִ֔י כְּ⁠ט֥וֹב לֵב־הַ⁠מֶּ֖לֶךְ בַּ⁠יָּ֑יִן אָמַ֡ר לִ֠⁠מְהוּמָן בִּזְּתָ֨א חַרְבוֹנָ֜א בִּגְתָ֤א וַ⁠אֲבַגְתָא֙ זֵתַ֣ר וְ⁠כַרְכַּ֔ס שִׁבְעַת֙ הַ⁠סָּ֣רִיסִ֔ים הַ⁠מְשָׁ֣רְתִ֔ים אֶת־פְּנֵ֖י הַ⁠מֶּ֥לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃","bȧ⁠ẏwòm֙ ha⁠şĕ̇̌biyʻi֔y kĕ̇⁠t֥wòb léb-ha⁠mė֖lekĕ bȧ⁠yá֑̇yin ʼáma֡r li֠⁠mĕhẇmán bi̇zĕ̇ţá֨ʼ ẖarĕbwòná֜ʼ bi̇gĕţá֤ʼ wa⁠ʼàbagĕţáʼ֙ zéţa֣r wĕ⁠karĕkȧ֔s şǐbĕʻaţ֙ ha⁠sá֣̇riysi֔ym ha⁠mĕşá֣̌rĕţi֔ym ʼeţ-pĕ̇né֖y ha⁠mė֥lekĕ ʼàẖaşĕ̌wérֽwòş̌׃"],[1,11,"לְ֠⁠הָבִיא אֶת־וַשְׁתִּ֧י הַ⁠מַּלְכָּ֛ה לִ⁠פְנֵ֥י הַ⁠מֶּ֖לֶךְ בְּ⁠כֶ֣תֶר מַלְכ֑וּת לְ⁠הַרְא֨וֹת הָֽ⁠עַמִּ֤ים וְ⁠הַ⁠שָּׂרִים֙ אֶת־יָפְיָ֔⁠הּ כִּֽי־טוֹבַ֥ת מַרְאֶ֖ה הִֽיא׃","lĕ֠⁠hábiyʼ ʼeţ-waşĕ̌ţi֧̇y ha⁠mȧlĕká֛̇h li⁠pĕné֥y ha⁠mė֖lekĕ bĕ̇⁠ke֣ţer malĕk֑ẇţ lĕ⁠harĕʼ֨wòţ háֽ⁠ʻami֤̇ym wĕ⁠ha⁠şá̇̂riym֙ ʼeţ-yápĕyá֔⁠ḣ kiֽ̇y-twòba֥ţ marĕʼe֖h hiֽyʼ׃"],[1,12,"וַ⁠תְּמָאֵ֞ן הַ⁠מַּלְכָּ֣ה וַשְׁתִּ֗י לָ⁠בוֹא֙ בִּ⁠דְבַ֣ר הַ⁠מֶּ֔לֶךְ אֲשֶׁ֖ר בְּ⁠יַ֣ד הַ⁠סָּרִיסִ֑ים וַ⁠יִּקְצֹ֤ף הַ⁠מֶּ֨לֶךְ֙ מְאֹ֔ד וַ⁠חֲמָת֖⁠וֹ בָּעֲרָ֥ה בֽ⁠וֹ׃","wa⁠ţĕ̇máʼé֞n ha⁠mȧlĕká֣̇h waşĕ̌ţi̇֗y lá⁠bwòʼ֙ bi̇⁠dĕba֣r ha⁠mė֔lekĕ ʼàşě֖r bĕ̇⁠ya֣d ha⁠sá̇riysi֑ym wa⁠yi̇qĕẕò֤p ha⁠mė֨lekĕ֙ mĕʼò֔d wa⁠ẖàmáţ֖⁠wò bá̇ʻàrá֥h bֽ⁠wò׃"],[1,13,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ לַ⁠חֲכָמִ֖ים יֹדְעֵ֣י הָֽ⁠עִתִּ֑ים כִּי־כֵן֙ דְּבַ֣ר הַ⁠מֶּ֔לֶךְ לִ⁠פְנֵ֕י כָּל־יֹדְעֵ֖י דָּ֥ת וָ⁠דִֽין׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ la⁠ẖàkámi֖ym yòdĕʻé֣y hֽá⁠ʻiţi֑̇ym ki̇y-kén֙ dĕ̇ba֣r ha⁠mė֔lekĕ li⁠pĕné֕y ká̇l-yòdĕʻé֖y dá֥̇ţ wá⁠diֽyn׃"],[1,14,"וְ⁠הַ⁠קָּרֹ֣ב אֵלָ֗י⁠ו כַּרְשְׁנָ֤א שֵׁתָר֙ אַדְמָ֣תָא תַרְשִׁ֔ישׁ מֶ֥רֶס מַרְסְנָ֖א מְמוּכָ֑ן שִׁבְעַ֞ת שָׂרֵ֣י ׀ פָּרַ֣ס וּ⁠מָדַ֗י רֹאֵי֙ פְּנֵ֣י הַ⁠מֶּ֔לֶךְ הַ⁠יֹּשְׁבִ֥ים רִאשֹׁנָ֖ה בַּ⁠מַּלְכֽוּת׃","wĕ⁠ha⁠qá̇rò֣b ʼélá֗y⁠w kȧrĕşĕ̌ná֤ʼ şé̌ţár֙ ʼadĕmá֣ţáʼ ţarĕşǐ֔yş̌ me֥res marĕsĕná֖ʼ mĕmẇká֑n şǐbĕʻa֞ţ şá̂ré֣y ׀ pá̇ra֣s ẇ⁠máda֗y ròʼéy֙ pĕ̇né֣y ha⁠mė֔lekĕ ha⁠yò̇şĕ̌bi֥ym riʼşò̌ná֖h bȧ⁠mȧlĕkֽẇţ׃"],[1,15,"כְּ⁠דָת֙ מַֽה־לַּ⁠עֲשׂ֔וֹת בַּ⁠מַּלְכָּ֖ה וַשְׁתִּ֑י עַ֣ל ׀ אֲשֶׁ֣ר לֹֽא־עָשְׂתָ֗ה אֶֽת־מַאֲמַר֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ בְּ⁠יַ֖ד הַ⁠סָּרִיסִֽים׃ס","kĕ̇⁠dáţ֙ maֽh-lȧ⁠ʻàş̂֔wòţ bȧ⁠mȧlĕká֖̇h waşĕ̌ţi֑̇y ʻa֣l ׀ ʼàşě֣r lòֽʼ-ʻáşĕ̂ţá֗h ʼeֽţ-maʼàmar֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ bĕ̇⁠ya֖d ha⁠sá̇riysiֽym׃s"],[1,16,"וַ⁠יֹּ֣אמֶר מומכן לִ⁠פְנֵ֤י הַ⁠מֶּ֨לֶךְ֙ וְ⁠הַ⁠שָּׂרִ֔ים לֹ֤א עַל־הַ⁠מֶּ֨לֶךְ֙ לְ⁠בַדּ֔⁠וֹ עָוְתָ֖ה וַשְׁתִּ֣י הַ⁠מַּלְכָּ֑ה כִּ֤י עַל־כָּל־הַ⁠שָּׂרִים֙ וְ⁠עַל־כָּל־הָ֣⁠עַמִּ֔ים אֲשֶׁ֕ר בְּ⁠כָל־מְדִינ֖וֹת הַ⁠מֶּ֥לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃","wa⁠yò֣̇ʼmer mwmkn li⁠pĕné֤y ha⁠mė֨lekĕ֙ wĕ⁠ha⁠şá̇̂ri֔ym lò֤ʼ ʻal-ha⁠mė֨lekĕ֙ lĕ⁠baḋ֔⁠wò ʻáwĕţá֖h waşĕ̌ţi֣̇y ha⁠mȧlĕká֑̇h ki֤̇y ʻal-ká̇l-ha⁠şá̇̂riym֙ wĕ⁠ʻal-ká̇l-há֣⁠ʻami̇֔ym ʼàşě֕r bĕ̇⁠kál-mĕdiyn֖wòţ ha⁠mė֥lekĕ ʼàẖaşĕ̌wérֽwòş̌׃"],[1,17,"כִּֽי־יֵצֵ֤א דְבַר־הַ⁠מַּלְכָּה֙ עַל־כָּל־הַ⁠נָּשִׁ֔ים לְ⁠הַבְז֥וֹת בַּעְלֵי⁠הֶ֖ן בְּ⁠עֵינֵי⁠הֶ֑ן בְּ⁠אָמְרָ֗⁠ם הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֡וֹשׁ אָמַ֞ר לְ⁠הָבִ֨יא אֶת־וַשְׁתִּ֧י הַ⁠מַּלְכָּ֛ה לְ⁠פָנָ֖י⁠ו וְ⁠לֹא־בָֽאָה׃","kiֽ̇y-yéẕé֤ʼ dĕbar-ha⁠mȧlĕká̇h֙ ʻal-ká̇l-ha⁠ná̇şǐ֔ym lĕ⁠habĕz֥wòţ bȧʻĕléy⁠he֖n bĕ̇⁠ʻéynéy⁠he֑n bĕ̇⁠ʼámĕrá֗⁠m ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֡wòş̌ ʼáma֞r lĕ⁠hábi֨yʼ ʼeţ-waşĕ̌ţi֧̇y ha⁠mȧlĕká֛̇h lĕ⁠páná֖y⁠w wĕ⁠lòʼ-báֽʼáh׃"],[1,18,"וְֽ⁠הַ⁠יּ֨וֹם הַ⁠זֶּ֜ה תֹּאמַ֣רְנָה ׀ שָׂר֣וֹת פָּֽרַס־וּ⁠מָדַ֗י אֲשֶׁ֤ר שָֽׁמְעוּ֙ אֶת־דְּבַ֣ר הַ⁠מַּלְכָּ֔ה לְ⁠כֹ֖ל שָׂרֵ֣י הַ⁠מֶּ֑לֶךְ וּ⁠כְ⁠דַ֖י בִּזָּי֥וֹן וָ⁠קָֽצֶף׃","wĕֽ⁠ha⁠ẏ֨wòm ha⁠zė֜h ţò̇ʼma֣rĕnáh ׀ şá̂r֣wòţ páֽ̇ras-ẇ⁠máda֗y ʼàşě֤r şáֽ̌mĕʻẇ֙ ʼeţ-dĕ̇ba֣r ha⁠mȧlĕká̇֔h lĕ⁠kò֖l şá̂ré֣y ha⁠mė֑lekĕ ẇ⁠kĕ⁠da֖y bi̇zá̇y֥wòn wá⁠qáֽẕep׃"],[1,19,"אִם־עַל־הַ⁠מֶּ֣לֶךְ ט֗וֹב יֵצֵ֤א דְבַר־מַלְכוּת֙ מִ⁠לְּ⁠פָנָ֔י⁠ו וְ⁠יִכָּתֵ֛ב בְּ⁠דָתֵ֥י פָֽרַס־וּ⁠מָדַ֖י וְ⁠לֹ֣א יַעֲב֑וֹר אֲשֶׁ֨ר לֹֽא־תָב֜וֹא וַשְׁתִּ֗י לִ⁠פְנֵי֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ וּ⁠מַלְכוּתָ⁠הּ֙ יִתֵּ֣ן הַ⁠מֶּ֔לֶךְ לִ⁠רְעוּתָ֖⁠הּ הַ⁠טּוֹבָ֥ה מִמֶּֽ⁠נָּה׃","ʼim-ʻal-ha⁠mė֣lekĕ t֗wòb yéẕé֤ʼ dĕbar-malĕkẇţ֙ mi⁠lĕ̇⁠páná֔y⁠w wĕ⁠yiká̇ţé֛b bĕ̇⁠dáţé֥y páֽras-ẇ⁠máda֖y wĕ⁠lò֣ʼ yaʻàb֑wòr ʼàşě֨r lòֽʼ-ţáb֜wòʼ waşĕ̌ţi̇֗y li⁠pĕnéy֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ ẇ⁠malĕkẇţá⁠ḣ֙ yiţé֣̇n ha⁠mė֔lekĕ li⁠rĕʻẇţá֖⁠ḣ ha⁠ṫwòbá֥h mimėֽ⁠ná̇h׃"],[1,20,"וְ⁠נִשְׁמַע֩ פִּתְגָ֨ם הַ⁠מֶּ֤לֶךְ אֲשֶֽׁר־יַעֲשֶׂה֙ בְּ⁠כָל־מַלְכוּת֔⁠וֹ כִּ֥י רַבָּ֖ה הִ֑יא וְ⁠כָל־הַ⁠נָּשִׁ֗ים יִתְּנ֤וּ יְקָר֙ לְ⁠בַעְלֵי⁠הֶ֔ן לְ⁠מִ⁠גָּד֖וֹל וְ⁠עַד־קָטָֽן׃","wĕ⁠nişĕ̌maʻ֩ pi̇ţĕgá֨m ha⁠mė֤lekĕ ʼàşěֽr-yaʻàşêh֙ bĕ̇⁠kál-malĕkẇţ֔⁠wò ki֥̇y rabá֖̇h hi֑yʼ wĕ⁠kál-ha⁠ná̇şǐ֗ym yiţĕ̇n֤ẇ yĕqár֙ lĕ⁠baʻĕléy⁠he֔n lĕ⁠mi⁠gá̇d֖wòl wĕ⁠ʻad-qátáֽn׃"],[1,21,"וַ⁠יִּיטַב֙ הַ⁠דָּבָ֔ר בְּ⁠עֵינֵ֥י הַ⁠מֶּ֖לֶךְ וְ⁠הַ⁠שָּׂרִ֑ים וַ⁠יַּ֥עַשׂ הַ⁠מֶּ֖לֶךְ כִּ⁠דְבַ֥ר מְמוּכָֽן׃","wa⁠yi̇ytab֙ ha⁠dá̇bá֔r bĕ̇⁠ʻéyné֥y ha⁠mė֖lekĕ wĕ⁠ha⁠şá̇̂ri֑ym wa⁠yȧ֥ʻaş̂ ha⁠mė֖lekĕ ki̇⁠dĕba֥r mĕmẇkáֽn׃"],[1,22,"וַ⁠יִּשְׁלַ֤ח סְפָרִים֙ אֶל־כָּל־מְדִינ֣וֹת הַ⁠מֶּ֔לֶךְ אֶל־מְדִינָ֤ה וּ⁠מְדִינָה֙ כִּ⁠כְתָבָ֔⁠הּ וְ⁠אֶל־עַ֥ם וָ⁠עָ֖ם כִּ⁠לְשׁוֹנ֑⁠וֹ לִ⁠הְי֤וֹת כָּל־אִישׁ֙ שֹׂרֵ֣ר בְּ⁠בֵית֔⁠וֹ וּ⁠מְדַבֵּ֖ר כִּ⁠לְשׁ֥וֹן עַמּֽ⁠וֹ׃פ","wa⁠yi̇şĕ̌la֤ẖ sĕpáriym֙ ʼel-ká̇l-mĕdiyn֣wòţ ha⁠mė֔lekĕ ʼel-mĕdiyná֤h ẇ⁠mĕdiynáh֙ ki̇⁠kĕţábá֔⁠ḣ wĕ⁠ʼel-ʻa֥m wá⁠ʻá֖m ki̇⁠lĕş̌wòn֑⁠wò li⁠hĕy֤wòţ ká̇l-ʼiyş̌֙ şò̂ré֣r bĕ̇⁠béyţ֔⁠wò ẇ⁠mĕdabé֖̇r ki̇⁠lĕş֥̌wòn ʻaṁֽ⁠wò׃p"],[2,1,"אַחַר֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה כְּ⁠שֹׁ֕ךְ חֲמַ֖ת הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֑וֹשׁ זָכַ֤ר אֶת־וַשְׁתִּי֙ וְ⁠אֵ֣ת אֲשֶׁר־עָשָׂ֔תָה וְ⁠אֵ֥ת אֲשֶׁר־נִגְזַ֖ר עָלֶֽי⁠הָ׃","ʼaẖar֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh kĕ̇⁠şò̌֕kĕ ẖàma֖ţ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֑wòş̌ záka֤r ʼeţ-waşĕ̌ţi̇y֙ wĕ⁠ʼé֣ţ ʼàşěr-ʻáşá̂֔ţáh wĕ⁠ʼé֥ţ ʼàşěr-nigĕza֖r ʻáleֽy⁠há׃"],[2,2,"וַ⁠יֹּאמְר֥וּ נַעֲרֵֽי־הַ⁠מֶּ֖לֶךְ מְשָׁרְתָ֑י⁠ו יְבַקְשׁ֥וּ לַ⁠מֶּ֛לֶךְ נְעָר֥וֹת בְּתוּל֖וֹת טוֹב֥וֹת מַרְאֶֽה׃","wa⁠yò̇ʼmĕr֥ẇ naʻàréֽy-ha⁠mė֖lekĕ mĕşá̌rĕţá֑y⁠w yĕbaqĕş֥̌ẇ la⁠mė֛lekĕ nĕʻár֥wòţ bĕ̇ţẇl֖wòţ twòb֥wòţ marĕʼeֽh׃"],[2,3,"וְ⁠יַפְקֵ֨ד הַ⁠מֶּ֣לֶךְ פְּקִידִים֮ בְּ⁠כָל־מְדִינ֣וֹת מַלְכוּת⁠וֹ֒ וְ⁠יִקְבְּצ֣וּ אֶת־כָּל־נַעֲרָֽה־בְ֠תוּלָה טוֹבַ֨ת מַרְאֶ֜ה אֶל־שׁוּשַׁ֤ן הַ⁠בִּירָה֙ אֶל־בֵּ֣ית הַ⁠נָּשִׁ֔ים אֶל־יַ֥ד הֵגֶ֛א סְרִ֥יס הַ⁠מֶּ֖לֶךְ שֹׁמֵ֣ר הַ⁠נָּשִׁ֑ים וְ⁠נָת֖וֹן תַּמְרוּקֵי⁠הֶֽן׃","wĕ⁠yapĕqé֨d ha⁠mė֣lekĕ pĕ̇qiydiym֮ bĕ̇⁠kál-mĕdiyn֣wòţ malĕkẇţ⁠wò֒ wĕ⁠yiqĕbĕ̇ẕ֣ẇ ʼeţ-ká̇l-naʻàráֽh-bĕ֠ţẇláh twòba֨ţ marĕʼe֜h ʼel-ş̌ẇşǎ֤n ha⁠bi̇yráh֙ ʼel-bé֣̇yţ ha⁠ná̇şǐ֔ym ʼel-ya֥d hége֛ʼ sĕri֥ys ha⁠mė֖lekĕ şò̌mé֣r ha⁠ná̇şǐ֑ym wĕ⁠náţ֖wòn ţȧmĕrẇqéy⁠heֽn׃"],[2,4,"וְ⁠הַֽ⁠נַּעֲרָ֗ה אֲשֶׁ֤ר תִּיטַב֙ בְּ⁠עֵינֵ֣י הַ⁠מֶּ֔לֶךְ תִּמְלֹ֖ךְ תַּ֣חַת וַשְׁתִּ֑י וַ⁠יִּיטַ֧ב הַ⁠דָּבָ֛ר בְּ⁠עֵינֵ֥י הַ⁠מֶּ֖לֶךְ וַ⁠יַּ֥עַשׂ כֵּֽן׃ס","wĕ⁠haֽ⁠nȧʻàrá֗h ʼàşě֤r ţi̇ytab֙ bĕ̇⁠ʻéyné֣y ha⁠mė֔lekĕ ţi̇mĕlò֖kĕ ţȧ֣ẖaţ waşĕ̌ţi֑̇y wa⁠yi̇yta֧b ha⁠dá̇bá֛r bĕ̇⁠ʻéyné֥y ha⁠mė֖lekĕ wa⁠yȧ֥ʻaş̂ kéֽ̇n׃s"],[2,5,"אִ֣ישׁ יְהוּדִ֔י הָיָ֖ה בְּ⁠שׁוּשַׁ֣ן הַ⁠בִּירָ֑ה וּ⁠שְׁמ֣⁠וֹ מָרְדֳּכַ֗י בֶּ֣ן יָאִ֧יר בֶּן־שִׁמְעִ֛י בֶּן־קִ֖ישׁ אִ֥ישׁ יְמִינִֽי׃","ʼi֣yş̌ yĕhẇdi֔y háyá֖h bĕ̇⁠ş̌ẇşǎ֣n ha⁠bi̇yrá֑h ẇ⁠şĕ̌m֣⁠wò márĕdȯka֗y bė֣n yáʼi֧yr bėn-şǐmĕʻi֛y bėn-qi֖yş̌ ʼi֥yş̌ yĕmiyniֽy׃"],[2,6,"אֲשֶׁ֤ר הָגְלָה֙ מִ⁠יר֣וּשָׁלַ֔יִם עִם־הַ⁠גֹּלָה֙ אֲשֶׁ֣ר הָגְלְתָ֔ה עִ֖ם יְכָנְיָ֣ה מֶֽלֶךְ־יְהוּדָ֑ה אֲשֶׁ֣ר הֶגְלָ֔ה נְבוּכַדְנֶאצַּ֖ר מֶ֥לֶךְ בָּבֶֽל׃","ʼàşě֤r hágĕláh֙ mi⁠yr֣ẇşá̌la֔yim ʻim-ha⁠gò̇láh֙ ʼàşě֣r hágĕlĕţá֔h ʻi֖m yĕkánĕyá֣h meֽlekĕ-yĕhẇdá֑h ʼàşě֣r hegĕlá֔h nĕbẇkadĕneʼẕȧ֖r me֥lekĕ bá̇beֽl׃"],[2,7,"וַ⁠יְהִ֨י אֹמֵ֜ן אֶת־הֲדַסָּ֗ה הִ֤יא אֶסְתֵּר֙ בַּת־דֹּד֔⁠וֹ כִּ֛י אֵ֥ין לָ֖⁠הּ אָ֣ב וָ⁠אֵ֑ם וְ⁠הַ⁠נַּעֲרָ֤ה יְפַת־תֹּ֨אַר֙ וְ⁠טוֹבַ֣ת מַרְאֶ֔ה וּ⁠בְ⁠מ֤וֹת אָבִ֨י⁠הָ֙ וְ⁠אִמָּ֔⁠הּ לְקָחָ֧⁠הּ מָרְדֳּכַ֛י ל֖⁠וֹ לְ⁠בַֽת׃","wa⁠yĕhi֨y ʼòmé֜n ʼeţ-hàdasá̇֗h hi֤yʼ ʼesĕţé̇r֙ bȧţ-dò̇d֔⁠wò ki֛̇y ʼé֥yn lá֖⁠ḣ ʼá֣b wá⁠ʼé֑m wĕ⁠ha⁠nȧʻàrá֤h yĕpaţ-ţò̇֨ʼar֙ wĕ⁠twòba֣ţ marĕʼe֔h ẇ⁠bĕ⁠m֤wòţ ʼábi֨y⁠há֙ wĕ⁠ʼimá̇֔⁠ḣ lĕqáẖá֧⁠ḣ márĕdȯka֛y l֖⁠wò lĕ⁠baֽţ׃"],[2,8,"וַ⁠יְהִ֗י בְּ⁠הִשָּׁמַ֤ע דְּבַר־הַ⁠מֶּ֨לֶךְ֙ וְ⁠דָת֔⁠וֹ וּֽ⁠בְ⁠הִקָּבֵ֞ץ נְעָר֥וֹת רַבּ֛וֹת אֶל־שׁוּשַׁ֥ן הַ⁠בִּירָ֖ה אֶל־יַ֣ד הֵגָ֑י וַ⁠תִּלָּקַ֤ח אֶסְתֵּר֙ אֶל־בֵּ֣ית הַ⁠מֶּ֔לֶךְ אֶל־יַ֥ד הֵגַ֖י שֹׁמֵ֥ר הַ⁠נָּשִֽׁים׃","wa⁠yĕhi֗y bĕ̇⁠hişá̇̌ma֤ʻ dĕ̇bar-ha⁠mė֨lekĕ֙ wĕ⁠dáţ֔⁠wò ẇֽ⁠bĕ⁠hiqá̇bé֞ẕ nĕʻár֥wòţ raḃ֛wòţ ʼel-ş̌ẇşǎ֥n ha⁠bi̇yrá֖h ʼel-ya֣d hégá֑y wa⁠ţi̇lá̇qa֤ẖ ʼesĕţé̇r֙ ʼel-bé֣̇yţ ha⁠mė֔lekĕ ʼel-ya֥d héga֖y şò̌mé֥r ha⁠ná̇şǐֽym׃"],[2,9,"וַ⁠תִּיטַ֨ב הַ⁠נַּעֲרָ֣ה בְ⁠עֵינָי⁠ו֮ וַ⁠תִּשָּׂ֣א חֶ֣סֶד לְ⁠פָנָי⁠ו֒ וַ֠⁠יְבַהֵל אֶת־תַּמְרוּקֶ֤י⁠הָ וְ⁠אֶת־מָנוֹתֶ֨⁠הָ֙ לָ⁠תֵ֣ת לָ֔⁠הּ וְ⁠אֵת֙ שֶׁ֣בַע הַ⁠נְּעָר֔וֹת הָ⁠רְאֻי֥וֹת לָֽ⁠תֶת־לָ֖⁠הּ מִ⁠בֵּ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יְשַׁנֶּ֧⁠הָ וְ⁠אֶת־נַעֲרוֹתֶ֛י⁠הָ לְ⁠ט֖וֹב בֵּ֥ית הַ⁠נָּשִֽׁים׃","wa⁠ţi̇yta֨b ha⁠nȧʻàrá֣h bĕ⁠ʻéynáy⁠w֮ wa⁠ţi̇şá֣̇̂ʼ ẖe֣sed lĕ⁠pánáy⁠w֒ wa֠⁠yĕbahél ʼeţ-ţȧmĕrẇqe֤y⁠há wĕ⁠ʼeţ-mánwòţe֨⁠há֙ lá⁠ţé֣ţ lá֔⁠ḣ wĕ⁠ʼéţ֙ şě֣baʻ ha⁠nĕ̇ʻár֔wòţ há⁠rĕʼuy֥wòţ láֽ⁠ţeţ-lá֖⁠ḣ mi⁠bé֣̇yţ ha⁠mė֑lekĕ wa⁠yĕşǎnė֧⁠há wĕ⁠ʼeţ-naʻàrwòţe֛y⁠há lĕ⁠t֖wòb bé֥̇yţ ha⁠ná̇şǐֽym׃"],[2,10,"לֹא־הִגִּ֣ידָה אֶסְתֵּ֔ר אֶת־עַמָּ֖⁠הּ וְ⁠אֶת־מֽוֹלַדְתָּ֑⁠הּ כִּ֧י מָרְדֳּכַ֛י צִוָּ֥ה עָלֶ֖י⁠הָ אֲשֶׁ֥ר לֹא־תַגִּֽיד׃","lòʼ-higi֣̇ydáh ʼesĕţé̇֔r ʼeţ-ʻamá֖̇⁠ḣ wĕ⁠ʼeţ-mֽwòladĕţá֑̇⁠ḣ ki֧̇y márĕdȯka֛y ẕiwá֥̇h ʻále֖y⁠há ʼàşě֥r lòʼ-ţagiֽ̇yd׃"],[2,11,"וּ⁠בְ⁠כָל־י֣וֹם וָ⁠י֔וֹם מָרְדֳּכַי֙ מִתְהַלֵּ֔ךְ לִ⁠פְנֵ֖י חֲצַ֣ר בֵּית־הַ⁠נָּשִׁ֑ים לָ⁠דַ֨עַת֙ אֶת־שְׁל֣וֹם אֶסְתֵּ֔ר וּ⁠מַה־יֵּעָשֶׂ֖ה בָּֽ⁠הּ׃","ẇ⁠bĕ⁠kál-y֣wòm wá⁠y֔wòm márĕdȯkay֙ miţĕhalé̇֔kĕ li⁠pĕné֖y ẖàẕa֣r bé̇yţ-ha⁠ná̇şǐ֑ym lá⁠da֨ʻaţ֙ ʼeţ-şĕ̌l֣wòm ʼesĕţé̇֔r ẇ⁠mah-yé̇ʻáşê֖h báֽ̇⁠ḣ׃"],[2,12,"וּ⁠בְ⁠הַגִּ֡יעַ תֹּר֩ נַעֲרָ֨ה וְ⁠נַעֲרָ֜ה לָ⁠ב֣וֹא ׀ אֶל־הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֗וֹשׁ מִ⁠קֵּץ֩ הֱי֨וֹת לָ֜⁠הּ כְּ⁠דָ֤ת הַ⁠נָּשִׁים֙ שְׁנֵ֣ים עָשָׂ֣ר חֹ֔דֶשׁ כִּ֛י כֵּ֥ן יִמְלְא֖וּ יְמֵ֣י מְרוּקֵי⁠הֶ֑ן שִׁשָּׁ֤ה חֳדָשִׁים֙ בְּ⁠שֶׁ֣מֶן הַ⁠מֹּ֔ר וְ⁠שִׁשָּׁ֤ה חֳדָשִׁים֙ בַּ⁠בְּשָׂמִ֔ים וּ⁠בְ⁠תַמְרוּקֵ֖י הַ⁠נָּשִֽׁים׃","ẇ⁠bĕ⁠hagi̇֡yʻa ţò̇r֩ naʻàrá֨h wĕ⁠naʻàrá֜h lá⁠b֣wòʼ ׀ ʼel-ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֗wòş̌ mi⁠qé̇ẕ֩ hèy֨wòţ lá֜⁠ḣ kĕ̇⁠dá֤ţ ha⁠ná̇şǐym֙ şĕ̌né֣ym ʻáşá֣̂r ẖò֔deş̌ ki֛̇y ké֥̇n yimĕlĕʼ֖ẇ yĕmé֣y mĕrẇqéy⁠he֑n şǐşá֤̇̌h ẖodáşǐym֙ bĕ̇⁠şě֣men ha⁠mò̇֔r wĕ⁠şǐşá֤̇̌h ẖodáşǐym֙ bȧ⁠bĕ̇şá̂mi֔ym ẇ⁠bĕ⁠ţamĕrẇqé֖y ha⁠ná̇şǐֽym׃"],[2,13,"וּ⁠בָ⁠זֶ֕ה הַֽ⁠נַּעֲרָ֖ה בָּאָ֣ה אֶל־הַ⁠מֶּ֑לֶךְ אֵת֩ כָּל־אֲשֶׁ֨ר תֹּאמַ֜ר יִנָּ֤תֵֽן לָ⁠הּ֙ לָ⁠ב֣וֹא עִמָּ֔⁠הּ מִ⁠בֵּ֥ית הַ⁠נָּשִׁ֖ים עַד־בֵּ֥ית הַ⁠מֶּֽלֶךְ׃","ẇ⁠bá⁠ze֕h haֽ⁠nȧʻàrá֖h bá̇ʼá֣h ʼel-ha⁠mė֑lekĕ ʼéţ֩ ká̇l-ʼàşě֨r ţò̇ʼma֜r yiná֤̇ţéֽn lá⁠ḣ֙ lá⁠b֣wòʼ ʻimá̇֔⁠ḣ mi⁠bé֥̇yţ ha⁠ná̇şǐ֖ym ʻad-bé֥̇yţ ha⁠mėֽlekĕ׃"],[2,14,"בָּ⁠עֶ֣רֶב ׀ הִ֣יא בָאָ֗ה וּ֠⁠בַ⁠בֹּקֶר הִ֣יא שָׁבָ֞ה אֶל־בֵּ֤ית הַ⁠נָּשִׁים֙ שֵׁנִ֔י אֶל־יַ֧ד שַֽׁעֲשְׁגַ֛ז סְרִ֥יס הַ⁠מֶּ֖לֶךְ שֹׁמֵ֣ר הַ⁠פִּֽילַגְשִׁ֑ים לֹא־תָב֥וֹא עוֹד֙ אֶל־הַ⁠מֶּ֔לֶךְ כִּ֣י אִם־חָפֵ֥ץ בָּ֛⁠הּ הַ⁠מֶּ֖לֶךְ וְ⁠נִקְרְאָ֥ה בְ⁠שֵֽׁם׃","bá̇⁠ʻe֣reb ׀ hi֣yʼ báʼá֗h ẇ֠⁠ba⁠bò̇qer hi֣yʼ şá̌bá֞h ʼel-bé֤̇yţ ha⁠ná̇şǐym֙ şé̌ni֔y ʼel-ya֧d şǎֽʻàşĕ̌ga֛z sĕri֥ys ha⁠mė֖lekĕ şò̌mé֣r ha⁠piֽ̇ylagĕşǐ֑ym lòʼ-ţáb֥wòʼ ʻwòd֙ ʼel-ha⁠mė֔lekĕ ki֣̇y ʼim-ẖápé֥ẕ bá֛̇⁠ḣ ha⁠mė֖lekĕ wĕ⁠niqĕrĕʼá֥h bĕ⁠şéֽ̌m׃"],[2,15,"וּ⁠בְ⁠הַגִּ֣יעַ תֹּר־אֶסְתֵּ֣ר בַּת־אֲבִיחַ֣יִל דֹּ֣ד מָרְדֳּכַ֡י אֲשֶׁר֩ לָקַֽח־ל֨⁠וֹ לְ⁠בַ֜ת לָ⁠ב֣וֹא אֶל־הַ⁠מֶּ֗לֶךְ לֹ֤א בִקְשָׁה֙ דָּבָ֔ר כִּ֠י אִ֣ם אֶת־אֲשֶׁ֥ר יֹאמַ֛ר הֵגַ֥י סְרִיס־הַ⁠מֶּ֖לֶךְ שֹׁמֵ֣ר הַ⁠נָּשִׁ֑ים וַ⁠תְּהִ֤י אֶסְתֵּר֙ נֹשֵׂ֣את חֵ֔ן בְּ⁠עֵינֵ֖י כָּל־רֹאֶֽי⁠הָ׃","ẇ⁠bĕ⁠hagi֣̇yʻa ţò̇r-ʼesĕţé֣̇r bȧţ-ʼàbiyẖa֣yil dò֣̇d márĕdȯka֡y ʼàşěr֩ láqaֽẖ-l֨⁠wò lĕ⁠ba֜ţ lá⁠b֣wòʼ ʼel-ha⁠mė֗lekĕ lò֤ʼ biqĕşá̌h֙ dá̇bá֔r ki̇֠y ʼi֣m ʼeţ-ʼàşě֥r yòʼma֛r héga֥y sĕriys-ha⁠mė֖lekĕ şò̌mé֣r ha⁠ná̇şǐ֑ym wa⁠ţĕ̇hi֤y ʼesĕţé̇r֙ nòşé֣̂ʼţ ẖé֔n bĕ̇⁠ʻéyné֖y ká̇l-ròʼeֽy⁠há׃"],[2,16,"וַ⁠תִּלָּקַ֨ח אֶסְתֵּ֜ר אֶל־הַ⁠מֶּ֤לֶךְ אֲחַשְׁוֵרוֹשׁ֙ אֶל־בֵּ֣ית מַלְכוּת֔⁠וֹ בַּ⁠חֹ֥דֶשׁ הָ⁠עֲשִׂירִ֖י הוּא־חֹ֣דֶשׁ טֵבֵ֑ת בִּ⁠שְׁנַת־שֶׁ֖בַע לְ⁠מַלְכוּתֽ⁠וֹ׃","wa⁠ţi̇lá̇qa֨ẖ ʼesĕţé̇֜r ʼel-ha⁠mė֤lekĕ ʼàẖaşĕ̌wérwòş̌֙ ʼel-bé֣̇yţ malĕkẇţ֔⁠wò bȧ⁠ẖò֥deş̌ há⁠ʻàşîyri֖y hẇʼ-ẖò֣deş̌ tébé֑ţ bi̇⁠şĕ̌naţ-şě֖baʻ lĕ⁠malĕkẇţֽ⁠wò׃"],[2,17,"וַ⁠יֶּאֱהַ֨ב הַ⁠מֶּ֤לֶךְ אֶת־אֶסְתֵּר֙ מִ⁠כָּל־הַ⁠נָּשִׁ֔ים וַ⁠תִּשָּׂא־חֵ֥ן וָ⁠חֶ֛סֶד לְ⁠פָנָ֖י⁠ו מִ⁠כָּל־הַ⁠בְּתוּלֹ֑ת וַ⁠יָּ֤שֶׂם כֶּֽתֶר־מַלְכוּת֙ בְּ⁠רֹאשָׁ֔⁠הּ וַ⁠יַּמְלִיכֶ֖⁠הָ תַּ֥חַת וַשְׁתִּֽי׃","wa⁠yėʼèha֨b ha⁠mė֤lekĕ ʼeţ-ʼesĕţé̇r֙ mi⁠ká̇l-ha⁠ná̇şǐ֔ym wa⁠ţi̇şá̇̂ʼ-ẖé֥n wá⁠ẖe֛sed lĕ⁠páná֖y⁠w mi⁠ká̇l-ha⁠bĕ̇ţẇlò֑ţ wa⁠yá֤̇şêm kėֽţer-malĕkẇţ֙ bĕ̇⁠ròʼşá̌֔⁠ḣ wa⁠yȧmĕliyke֖⁠há ţȧ֥ẖaţ waşĕ̌ţiֽ̇y׃"],[2,18,"וַ⁠יַּ֨עַשׂ הַ⁠מֶּ֜לֶךְ מִשְׁתֶּ֣ה גָד֗וֹל לְ⁠כָל־שָׂרָי⁠ו֙ וַ⁠עֲבָדָ֔י⁠ו אֵ֖ת מִשְׁתֵּ֣ה אֶסְתֵּ֑ר וַ⁠הֲנָחָ֤ה לַ⁠מְּדִינוֹת֙ עָשָׂ֔ה וַ⁠יִּתֵּ֥ן מַשְׂאֵ֖ת כְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wa⁠yȧ֨ʻaş̂ ha⁠mė֜lekĕ mişĕ̌ţė֣h gád֗wòl lĕ⁠kál-şá̂ráy⁠w֙ wa⁠ʻàbádá֔y⁠w ʼé֖ţ mişĕ̌ţé֣̇h ʼesĕţé֑̇r wa⁠hànáẖá֤h la⁠mĕ̇diynwòţ֙ ʻáşá̂֔h wa⁠yi̇ţé֥̇n maşĕ̂ʼé֖ţ kĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[2,19,"וּ⁠בְ⁠הִקָּבֵ֥ץ בְּתוּל֖וֹת שֵׁנִ֑ית וּ⁠מָרְדֳּכַ֖י יֹשֵׁ֥ב בְּ⁠שַֽׁעַר־הַ⁠מֶּֽלֶךְ׃","ẇ⁠bĕ⁠hiqá̇bé֥ẕ bĕ̇ţẇl֖wòţ şé̌ni֑yţ ẇ⁠márĕdȯka֖y yòşé֥̌b bĕ̇⁠şǎֽʻar-ha⁠mėֽlekĕ׃"],[2,20,"אֵ֣ין אֶסְתֵּ֗ר מַגֶּ֤דֶת מֽוֹלַדְתָּ⁠הּ֙ וְ⁠אֶת־עַמָּ֔⁠הּ כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה עָלֶ֖י⁠הָ מָרְדֳּכָ֑י וְ⁠אֶת־מַאֲמַ֤ר מָרְדֳּכַי֙ אֶסְתֵּ֣ר עֹשָׂ֔ה כַּ⁠אֲשֶׁ֛ר הָיְתָ֥ה בְ⁠אָמְנָ֖ה אִתּֽ⁠וֹ׃ס","ʼé֣yn ʼesĕţé̇֗r magė֤deţ mֽwòladĕţá̇⁠ḣ֙ wĕ⁠ʼeţ-ʻamá̇֔⁠ḣ kȧ⁠ʼàşě֛r ẕiwá֥̇h ʻále֖y⁠há márĕdȯká֑y wĕ⁠ʼeţ-maʼàma֤r márĕdȯkay֙ ʼesĕţé֣̇r ʻòşá̂֔h kȧ⁠ʼàşě֛r háyĕţá֥h bĕ⁠ʼámĕná֖h ʼiţֽ̇⁠wò׃s"],[2,21,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם וּ⁠מָרְדֳּכַ֖י יֹשֵׁ֣ב בְּ⁠שַֽׁעַר־הַ⁠מֶּ֑לֶךְ קָצַף֩ בִּגְתָ֨ן וָ⁠תֶ֜רֶשׁ שְׁנֵֽי־סָרִיסֵ֤י הַ⁠מֶּ֨לֶךְ֙ מִ⁠שֹּׁמְרֵ֣י הַ⁠סַּ֔ף וַ⁠יְבַקְשׁוּ֙ לִ⁠שְׁלֹ֣חַ יָ֔ד בַּ⁠מֶּ֖לֶךְ אֲחַשְׁוֵֽרֹשׁ׃","bȧ⁠yá̇mi֣ym há⁠hé֔m ẇ⁠márĕdȯka֖y yòşé֣̌b bĕ̇⁠şǎֽʻar-ha⁠mė֑lekĕ qáẕap֩ bi̇gĕţá֨n wá⁠ţe֜reş̌ şĕ̌néֽy-sáriysé֤y ha⁠mė֨lekĕ֙ mi⁠şò̇̌mĕré֣y ha⁠sȧ֔p wa⁠yĕbaqĕş̌ẇ֙ li⁠şĕ̌lò֣ẖa yá֔d bȧ⁠mė֖lekĕ ʼàẖaşĕ̌wéֽròş̌׃"],[2,22,"וַ⁠יִּוָּדַ֤ע הַ⁠דָּבָר֙ לְ⁠מָרְדֳּכַ֔י וַ⁠יַּגֵּ֖ד לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֑ה וַ⁠תֹּ֧אמֶר אֶסְתֵּ֛ר לַ⁠מֶּ֖לֶךְ בְּ⁠שֵׁ֥ם מָרְדֳּכָֽי׃","wa⁠yi̇wá̇da֤ʻ ha⁠dá̇bár֙ lĕ⁠márĕdȯka֔y wa⁠yȧgé֖̇d lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká֑̇h wa⁠ţò֧̇ʼmer ʼesĕţé֛̇r la⁠mė֖lekĕ bĕ̇⁠şé֥̌m márĕdȯkáֽy׃"],[2,23,"וַ⁠יְבֻקַּ֤שׁ הַ⁠דָּבָר֙ וַ⁠יִּמָּצֵ֔א וַ⁠יִּתָּל֥וּ שְׁנֵי⁠הֶ֖ם עַל־עֵ֑ץ וַ⁠יִּכָּתֵ֗ב בְּ⁠סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃פ","wa⁠yĕbuqȧ֤ş̌ ha⁠dá̇bár֙ wa⁠yi̇má̇ẕé֔ʼ wa⁠yi̇ţá̇l֥ẇ şĕ̌néy⁠he֖m ʻal-ʻé֑ẕ wa⁠yi̇ká̇ţé֗b bĕ̇⁠sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym li⁠pĕné֥y ha⁠mėֽlekĕ׃p"],[3,1,"אַחַ֣ר ׀ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֗לֶּה גִּדַּל֩ הַ⁠מֶּ֨לֶךְ אֲחַשְׁוֵר֜וֹשׁ אֶת־הָמָ֧ן בֶּֽן־הַמְּדָ֛תָא הָ⁠אֲגָגִ֖י וַֽ⁠יְנַשְּׂאֵ֑⁠הוּ וַ⁠יָּ֨שֶׂם֙ אֶת־כִּסְא֔⁠וֹ מֵ⁠עַ֕ל כָּל־הַ⁠שָּׂרִ֖ים אֲשֶׁ֥ר אִתּֽ⁠וֹ׃","ʼaẖa֣r ׀ ha⁠dĕ̇bári֣ym há⁠ʼé֗lėh gi̇dȧl֩ ha⁠mė֨lekĕ ʼàẖaşĕ̌wér֜wòş̌ ʼeţ-hámá֧n bėֽn-hamĕ̇dá֛ţáʼ há⁠ʼàgági֖y waֽ⁠yĕnaşĕ̇̂ʼé֑⁠hẇ wa⁠yá̇֨şêm֙ ʼeţ-ki̇sĕʼ֔⁠wò mé⁠ʻa֕l ká̇l-ha⁠şá̇̂ri֖ym ʼàşě֥r ʼiţֽ̇⁠wò׃"],[3,2,"וְ⁠כָל־עַבְדֵ֨י הַ⁠מֶּ֜לֶךְ אֲשֶׁר־בְּ⁠שַׁ֣עַר הַ⁠מֶּ֗לֶךְ כֹּרְעִ֤ים וּ⁠מִֽשְׁתַּחֲוִים֙ לְ⁠הָמָ֔ן כִּי־כֵ֖ן צִוָּה־ל֣⁠וֹ הַ⁠מֶּ֑לֶךְ וּ⁠מָ֨רְדֳּכַ֔י לֹ֥א יִכְרַ֖ע וְ⁠לֹ֥א יִֽשְׁתַּחֲוֶֽה׃","wĕ⁠kál-ʻabĕdé֨y ha⁠mė֜lekĕ ʼàşěr-bĕ̇⁠şǎ֣ʻar ha⁠mė֗lekĕ kò̇rĕʻi֤ym ẇ⁠miֽşĕ̌ţȧẖàwiym֙ lĕ⁠hámá֔n ki̇y-ké֖n ẕiwá̇h-l֣⁠wò ha⁠mė֑lekĕ ẇ⁠má֨rĕdȯka֔y lò֥ʼ yikĕra֖ʻ wĕ⁠lò֥ʼ yiֽşĕ̌ţȧẖàweֽh׃"],[3,3,"וַ⁠יֹּ֨אמְר֜וּ עַבְדֵ֥י הַ⁠מֶּ֛לֶךְ אֲשֶׁר־בְּ⁠שַׁ֥עַר הַ⁠מֶּ֖לֶךְ לְ⁠מָרְדֳּכָ֑י מַדּ֨וּעַ֙ אַתָּ֣ה עוֹבֵ֔ר אֵ֖ת מִצְוַ֥ת הַ⁠מֶּֽלֶךְ׃","wa⁠yò̇֨ʼmĕr֜ẇ ʻabĕdé֥y ha⁠mė֛lekĕ ʼàşěr-bĕ̇⁠şǎ֥ʻar ha⁠mė֖lekĕ lĕ⁠márĕdȯká֑y maḋ֨ẇʻa֙ ʼaţá֣̇h ʻwòbé֔r ʼé֖ţ miẕĕwa֥ţ ha⁠mėֽlekĕ׃"],[3,4,"וַ⁠יְהִ֗י ב⁠אמר⁠ם אֵלָי⁠ו֙ י֣וֹם וָ⁠י֔וֹם וְ⁠לֹ֥א שָׁמַ֖ע אֲלֵי⁠הֶ֑ם וַ⁠יַּגִּ֣ידוּ לְ⁠הָמָ֗ן לִ⁠רְאוֹת֙ הֲ⁠יַֽעַמְדוּ֙ דִּבְרֵ֣י מָרְדֳּכַ֔י כִּֽי־הִגִּ֥יד לָ⁠הֶ֖ם אֲשֶׁר־ה֥וּא יְהוּדִֽי׃","wa⁠yĕhi֗y b⁠ʼmr⁠m ʼéláy⁠w֙ y֣wòm wá⁠y֔wòm wĕ⁠lò֥ʼ şá̌ma֖ʻ ʼàléy⁠he֑m wa⁠yȧgi֣̇ydẇ lĕ⁠hámá֗n li⁠rĕʼwòţ֙ hà⁠yaֽʻamĕdẇ֙ di̇bĕré֣y márĕdȯka֔y kiֽ̇y-higi֥̇yd lá⁠he֖m ʼàşěr-h֥ẇʼ yĕhẇdiֽy׃"],[3,5,"וַ⁠יַּ֣רְא הָמָ֔ן כִּי־אֵ֣ין מָרְדֳּכַ֔י כֹּרֵ֥עַ וּ⁠מִֽשְׁתַּחֲוֶ֖ה ל֑⁠וֹ וַ⁠יִּמָּלֵ֥א הָמָ֖ן חֵמָֽה׃","wa⁠yȧ֣rĕʼ hámá֔n ki̇y-ʼé֣yn márĕdȯka֔y kò̇ré֥ʻa ẇ⁠miֽşĕ̌ţȧẖàwe֖h l֑⁠wò wa⁠yi̇má̇lé֥ʼ hámá֖n ẖémáֽh׃"],[3,6,"וַ⁠יִּ֣בֶז בְּ⁠עֵינָ֗י⁠ו לִ⁠שְׁלֹ֤ח יָד֙ בְּ⁠מָרְדֳּכַ֣י לְ⁠בַדּ֔⁠וֹ כִּֽי־הִגִּ֥ידוּ ל֖⁠וֹ אֶת־עַ֣ם מָרְדֳּכָ֑י וַ⁠יְבַקֵּ֣שׁ הָמָ֗ן לְ⁠הַשְׁמִ֧יד אֶת־כָּל־הַ⁠יְּהוּדִ֛ים אֲשֶׁ֛ר בְּ⁠כָל־מַלְכ֥וּת אֲחַשְׁוֵר֖וֹשׁ עַ֥ם מָרְדֳּכָֽי׃","wa⁠yi֣̇bez bĕ̇⁠ʻéyná֗y⁠w li⁠şĕ̌lò֤ẖ yád֙ bĕ̇⁠márĕdȯka֣y lĕ⁠baḋ֔⁠wò kiֽ̇y-higi֥̇ydẇ l֖⁠wò ʼeţ-ʻa֣m márĕdȯká֑y wa⁠yĕbaqé֣̇ş̌ hámá֗n lĕ⁠haşĕ̌mi֧yd ʼeţ-ká̇l-ha⁠yĕ̇hẇdi֛ym ʼàşě֛r bĕ̇⁠kál-malĕk֥ẇţ ʼàẖaşĕ̌wér֖wòş̌ ʻa֥m márĕdȯkáֽy׃"],[3,7,"בַּ⁠חֹ֤דֶשׁ הָ⁠רִאשׁוֹן֙ הוּא־חֹ֣דֶשׁ נִיסָ֔ן בִּ⁠שְׁנַת֙ שְׁתֵּ֣ים עֶשְׂרֵ֔ה לַ⁠מֶּ֖לֶךְ אֲחַשְׁוֵר֑וֹשׁ הִפִּ֣יל פּוּר֩ ה֨וּא הַ⁠גּוֹרָ֜ל לִ⁠פְנֵ֣י הָמָ֗ן מִ⁠יּ֧וֹם ׀ לְ⁠י֛וֹם וּ⁠מֵ⁠חֹ֛דֶשׁ לְ⁠חֹ֥דֶשׁ שְׁנֵים־עָשָׂ֖ר הוּא־חֹ֥דֶשׁ אֲדָֽר׃ס","bȧ⁠ẖò֤deş̌ há⁠riʼş̌wòn֙ hẇʼ-ẖò֣deş̌ niysá֔n bi̇⁠şĕ̌naţ֙ şĕ̌ţé֣̇ym ʻeşĕ̂ré֔h la⁠mė֖lekĕ ʼàẖaşĕ̌wér֑wòş̌ hipi֣̇yl ṗẇr֩ h֨ẇʼ ha⁠ġwòrá֜l li⁠pĕné֣y hámá֗n mi⁠ẏ֧wòm ׀ lĕ⁠y֛wòm ẇ⁠mé⁠ẖò֛deş̌ lĕ⁠ẖò֥deş̌ şĕ̌néym-ʻáşá֖̂r hẇʼ-ẖò֥deş̌ ʼàdáֽr׃s"],[3,8,"וַ⁠יֹּ֤אמֶר הָמָן֙ לַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ יֶשְׁנ֣⁠וֹ עַם־אֶחָ֗ד מְפֻזָּ֤ר וּ⁠מְפֹרָד֙ בֵּ֣ין הָֽ⁠עַמִּ֔ים בְּ⁠כֹ֖ל מְדִינ֣וֹת מַלְכוּתֶ֑⁠ךָ וְ⁠דָתֵי⁠הֶ֞ם שֹׁנ֣וֹת מִ⁠כָּל־עָ֗ם וְ⁠אֶת־דָּתֵ֤י הַ⁠מֶּ֨לֶךְ֙ אֵינָ֣⁠ם עֹשִׂ֔ים וְ⁠לַ⁠מֶּ֥לֶךְ אֵין־שֹׁוֶ֖ה לְ⁠הַנִּיחָֽ⁠ם׃","wa⁠yò֤̇ʼmer hámán֙ la⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ yeşĕ̌n֣⁠wò ʻam-ʼeẖá֗d mĕpuzá֤̇r ẇ⁠mĕpòrád֙ bé֣̇yn háֽ⁠ʻami̇֔ym bĕ̇⁠kò֖l mĕdiyn֣wòţ malĕkẇţe֑⁠ká wĕ⁠dáţéy⁠he֞m şò̌n֣wòţ mi⁠ká̇l-ʻá֗m wĕ⁠ʼeţ-dá̇ţé֤y ha⁠mė֨lekĕ֙ ʼéyná֣⁠m ʻòşî֔ym wĕ⁠la⁠mė֥lekĕ ʼéyn-şò̌we֖h lĕ⁠hani̇yẖáֽ⁠m׃"],[3,9,"אִם־עַל־הַ⁠מֶּ֣לֶךְ ט֔וֹב יִכָּתֵ֖ב לְ⁠אַבְּדָ֑⁠ם וַ⁠עֲשֶׂ֨רֶת אֲלָפִ֜ים כִּכַּר־כֶּ֗סֶף אֶשְׁקוֹל֙ עַל־יְדֵי֙ עֹשֵׂ֣י הַ⁠מְּלָאכָ֔ה לְ⁠הָבִ֖יא אֶל־גִּנְזֵ֥י הַ⁠מֶּֽלֶךְ׃","ʼim-ʻal-ha⁠mė֣lekĕ t֔wòb yiká̇ţé֖b lĕ⁠ʼabĕ̇dá֑⁠m wa⁠ʻàşê֨reţ ʼàlápi֜ym ki̇kȧr-kė֗sep ʼeşĕ̌qwòl֙ ʻal-yĕdéy֙ ʻòşé֣̂y ha⁠mĕ̇láʼká֔h lĕ⁠hábi֖yʼ ʼel-gi̇nĕzé֥y ha⁠mėֽlekĕ׃"],[3,10,"וַ⁠יָּ֧סַר הַ⁠מֶּ֛לֶךְ אֶת־טַבַּעְתּ֖⁠וֹ מֵ⁠עַ֣ל יָד֑⁠וֹ וַֽ⁠יִּתְּנָ֗⁠הּ לְ⁠הָמָ֧ן בֶּֽן־הַמְּדָ֛תָא הָ⁠אֲגָגִ֖י צֹרֵ֥ר הַ⁠יְּהוּדִֽים׃","wa⁠yá֧̇sar ha⁠mė֛lekĕ ʼeţ-tabȧʻĕţ֖̇⁠wò mé⁠ʻa֣l yád֑⁠wò waֽ⁠yi̇ţĕ̇ná֗⁠ḣ lĕ⁠hámá֧n bėֽn-hamĕ̇dá֛ţáʼ há⁠ʼàgági֖y ẕòré֥r ha⁠yĕ̇hẇdiֽym׃"],[3,11,"וַ⁠יֹּ֤אמֶר הַ⁠מֶּ֨לֶךְ֙ לְ⁠הָמָ֔ן הַ⁠כֶּ֖סֶף נָת֣וּן לָ֑⁠ךְ וְ⁠הָ⁠עָ֕ם לַ⁠עֲשׂ֥וֹת בּ֖⁠וֹ כַּ⁠טּ֥וֹב בְּ⁠עֵינֶֽי⁠ךָ׃","wa⁠yò֤̇ʼmer ha⁠mė֨lekĕ֙ lĕ⁠hámá֔n ha⁠kė֖sep náţ֣ẇn lá֑⁠kĕ wĕ⁠há⁠ʻá֕m la⁠ʻàş֥̂wòţ ḃ֖⁠wò kȧ⁠ṫ֥wòb bĕ̇⁠ʻéyneֽy⁠ká׃"],[3,12,"וַ⁠יִּקָּרְאוּ֩ סֹפְרֵ֨י הַ⁠מֶּ֜לֶךְ בַּ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֗וֹן בִּ⁠שְׁלוֹשָׁ֨ה עָשָׂ֣ר יוֹם֮ בּ⁠וֹ֒ וַ⁠יִּכָּתֵ֣ב כְּֽ⁠כָל־אֲשֶׁר־צִוָּ֣ה הָמָ֡ן אֶ֣ל אֲחַשְׁדַּרְפְּנֵֽי־הַ֠⁠מֶּלֶךְ וְֽ⁠אֶל־הַ⁠פַּח֞וֹת אֲשֶׁ֣ר ׀ עַל־מְדִינָ֣ה וּ⁠מְדִינָ֗ה וְ⁠אֶל־שָׂ֤רֵי עַם֙ וָ⁠עָ֔ם מְדִינָ֤ה וּ⁠מְדִינָה֙ כִּ⁠כְתָבָ֔⁠הּ וְ⁠עַ֥ם וָ⁠עָ֖ם כִּ⁠לְשׁוֹנ֑⁠וֹ בְּ⁠שֵׁ֨ם הַ⁠מֶּ֤לֶךְ אֲחַשְׁוֵרֹשׁ֙ נִכְתָּ֔ב וְ⁠נֶחְתָּ֖ם בְּ⁠טַבַּ֥עַת הַ⁠מֶּֽלֶךְ׃","wa⁠yi̇qá̇rĕʼẇ֩ sòpĕré֨y ha⁠mė֜lekĕ bȧ⁠ẖò֣deş̌ há⁠riʼş̌֗wòn bi̇⁠şĕ̌lwòşá̌֨h ʻáşá֣̂r ywòm֮ ḃ⁠wò֒ wa⁠yi̇ká̇ţé֣b kĕֽ̇⁠kál-ʼàşěr-ẕiwá֣̇h hámá֡n ʼe֣l ʼàẖaşĕ̌dȧrĕpĕ̇néֽy-ha֠⁠mėlekĕ wĕֽ⁠ʼel-ha⁠pȧẖ֞wòţ ʼàşě֣r ׀ ʻal-mĕdiyná֣h ẇ⁠mĕdiyná֗h wĕ⁠ʼel-şá֤̂réy ʻam֙ wá⁠ʻá֔m mĕdiyná֤h ẇ⁠mĕdiynáh֙ ki̇⁠kĕţábá֔⁠ḣ wĕ⁠ʻa֥m wá⁠ʻá֖m ki̇⁠lĕş̌wòn֑⁠wò bĕ̇⁠şé̌֨m ha⁠mė֤lekĕ ʼàẖaşĕ̌wéròş̌֙ nikĕţá̇֔b wĕ⁠neẖĕţá֖̇m bĕ̇⁠tabȧ֥ʻaţ ha⁠mėֽlekĕ׃"],[3,13,"וְ⁠נִשְׁל֨וֹחַ סְפָרִ֜ים בְּ⁠יַ֣ד הָ⁠רָצִים֮ אֶל־כָּל־מְדִינ֣וֹת הַ⁠מֶּלֶךְ֒ לְ⁠הַשְׁמִ֡יד לַ⁠הֲרֹ֣ג וּ⁠לְ⁠אַבֵּ֣ד אֶת־כָּל־הַ֠⁠יְּהוּדִים מִ⁠נַּ֨עַר וְ⁠עַד־זָקֵ֜ן טַ֤ף וְ⁠נָשִׁים֙ בְּ⁠י֣וֹם אֶחָ֔ד בִּ⁠שְׁלוֹשָׁ֥ה עָשָׂ֛ר לְ⁠חֹ֥דֶשׁ שְׁנֵים־עָשָׂ֖ר הוּא־חֹ֣דֶשׁ אֲדָ֑ר וּ⁠שְׁלָלָ֖⁠ם לָ⁠בֽוֹז׃","wĕ⁠nişĕ̌l֨wòẖa sĕpári֜ym bĕ̇⁠ya֣d há⁠ráẕiym֮ ʼel-ká̇l-mĕdiyn֣wòţ ha⁠mėlekĕ֒ lĕ⁠haşĕ̌mi֡yd la⁠hàrò֣g ẇ⁠lĕ⁠ʼabé֣̇d ʼeţ-ká̇l-ha֠⁠yĕ̇hẇdiym mi⁠nȧ֨ʻar wĕ⁠ʻad-záqé֜n ta֤p wĕ⁠náşǐym֙ bĕ̇⁠y֣wòm ʼeẖá֔d bi̇⁠şĕ̌lwòşá֥̌h ʻáşá֛̂r lĕ⁠ẖò֥deş̌ şĕ̌néym-ʻáşá֖̂r hẇʼ-ẖò֣deş̌ ʼàdá֑r ẇ⁠şĕ̌lálá֖⁠m lá⁠bֽwòz׃"],[3,14,"פַּתְשֶׁ֣גֶן הַ⁠כְּתָ֗ב לְ⁠הִנָּ֤תֵֽן דָּת֙ בְּ⁠כָל־מְדִינָ֣ה וּ⁠מְדִינָ֔ה גָּל֖וּי לְ⁠כָל־הָֽ⁠עַמִּ֑ים לִ⁠הְי֥וֹת עֲתִדִ֖ים לַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","pȧţĕşě֣gen ha⁠kĕ̇ţá֗b lĕ⁠hiná֤̇ţéֽn dá̇ţ֙ bĕ̇⁠kál-mĕdiyná֣h ẇ⁠mĕdiyná֔h gá̇l֖ẇy lĕ⁠kál-háֽ⁠ʻami֑̇ym li⁠hĕy֥wòţ ʻàţidi֖ym la⁠ẏ֥wòm ha⁠zėֽh׃"],[3,15,"הָֽ⁠רָצִ֞ים יָצְא֤וּ דְחוּפִים֙ בִּ⁠דְבַ֣ר הַ⁠מֶּ֔לֶךְ וְ⁠הַ⁠דָּ֥ת נִתְּנָ֖ה בְּ⁠שׁוּשַׁ֣ן הַ⁠בִּירָ֑ה וְ⁠הַ⁠מֶּ֤לֶךְ וְ⁠הָמָן֙ יָשְׁב֣וּ לִ⁠שְׁתּ֔וֹת וְ⁠הָ⁠עִ֥יר שׁוּשָׁ֖ן נָבֽוֹכָה׃פ","hֽá⁠ráẕi֞ym yáẕĕʼ֤ẇ dĕẖẇpiym֙ bi̇⁠dĕba֣r ha⁠mė֔lekĕ wĕ⁠ha⁠dá֥̇ţ niţĕ̇ná֖h bĕ̇⁠ş̌ẇşǎ֣n ha⁠bi̇yrá֑h wĕ⁠ha⁠mė֤lekĕ wĕ⁠hámán֙ yáşĕ̌b֣ẇ li⁠şĕ̌ţ̇֔wòţ wĕ⁠há⁠ʻi֥yr ş̌ẇşá֖̌n nábֽwòkáh׃p"],[4,1,"וּ⁠מָרְדֳּכַ֗י יָדַע֙ אֶת־כָּל־אֲשֶׁ֣ר נַעֲשָׂ֔ה וַ⁠יִּקְרַ֤ע מָרְדֳּכַי֙ אֶת־בְּגָדָ֔י⁠ו וַ⁠יִּלְבַּ֥שׁ שַׂ֖ק וָ⁠אֵ֑פֶר וַ⁠יֵּצֵא֙ בְּ⁠ת֣וֹךְ הָ⁠עִ֔יר וַ⁠יִּזְעַ֛ק זְעָקָ֥ה גְדֹלָ֖ה וּ⁠מָרָֽה׃","ẇ⁠márĕdȯka֗y yádaʻ֙ ʼeţ-ká̇l-ʼàşě֣r naʻàşá̂֔h wa⁠yi̇qĕra֤ʻ márĕdȯkay֙ ʼeţ-bĕ̇gádá֔y⁠w wa⁠yi̇lĕbȧ֥ş̌ şâ֖q wá⁠ʼé֑per wa⁠yé̇ẕéʼ֙ bĕ̇⁠ţ֣wòkĕ há⁠ʻi֔yr wa⁠yi̇zĕʻa֛q zĕʻáqá֥h gĕdòlá֖h ẇ⁠máráֽh׃"],[4,2,"וַ⁠יָּב֕וֹא עַ֖ד לִ⁠פְנֵ֣י שַֽׁעַר־הַ⁠מֶּ֑לֶךְ כִּ֣י אֵ֥ין לָ⁠ב֛וֹא אֶל־שַׁ֥עַר הַ⁠מֶּ֖לֶךְ בִּ⁠לְב֥וּשׁ שָֽׂק׃","wa⁠yá̇b֕wòʼ ʻa֖d li⁠pĕné֣y şǎֽʻar-ha⁠mė֑lekĕ ki֣̇y ʼé֥yn lá⁠b֛wòʼ ʼel-şǎ֥ʻar ha⁠mė֖lekĕ bi̇⁠lĕb֥ẇş̌ şáֽ̂q׃"],[4,3,"וּ⁠בְ⁠כָל־מְדִינָ֣ה וּ⁠מְדִינָ֗ה מְקוֹם֙ אֲשֶׁ֨ר דְּבַר־הַ⁠מֶּ֤לֶךְ וְ⁠דָת⁠וֹ֙ מַגִּ֔יעַ אֵ֤בֶל גָּדוֹל֙ לַ⁠יְּהוּדִ֔ים וְ⁠צ֥וֹם וּ⁠בְכִ֖י וּ⁠מִסְפֵּ֑ד שַׂ֣ק וָ⁠אֵ֔פֶר יֻצַּ֖ע לָֽ⁠רַבִּֽים׃","ẇ⁠bĕ⁠kál-mĕdiyná֣h ẇ⁠mĕdiyná֗h mĕqwòm֙ ʼàşě֨r dĕ̇bar-ha⁠mė֤lekĕ wĕ⁠dáţ⁠wò֙ magi̇֔yʻa ʼé֤bel gá̇dwòl֙ la⁠yĕ̇hẇdi֔ym wĕ⁠ẕ֥wòm ẇ⁠bĕki֖y ẇ⁠misĕpé֑̇d şâ֣q wá⁠ʼé֔per yuẕȧ֖ʻ láֽ⁠rabiֽ̇ym׃"],[4,4,"ותבואינה נַעֲר֨וֹת אֶסְתֵּ֤ר וְ⁠סָרִיסֶ֨י⁠הָ֙ וַ⁠יַּגִּ֣ידוּ לָ֔⁠הּ וַ⁠תִּתְחַלְחַ֥ל הַ⁠מַּלְכָּ֖ה מְאֹ֑ד וַ⁠תִּשְׁלַ֨ח בְּגָדִ֜ים לְ⁠הַלְבִּ֣ישׁ אֶֽת־מָרְדֳּכַ֗י וּ⁠לְ⁠הָסִ֥יר שַׂקּ֛⁠וֹ מֵ⁠עָלָ֖י⁠ו וְ⁠לֹ֥א קִבֵּֽל׃","wţbwʼynh naʻàr֨wòţ ʼesĕţé֤̇r wĕ⁠sáriyse֨y⁠há֙ wa⁠yȧgi֣̇ydẇ lá֔⁠ḣ wa⁠ţi̇ţĕẖalĕẖa֥l ha⁠mȧlĕká֖̇h mĕʼò֑d wa⁠ţi̇şĕ̌la֨ẖ bĕ̇gádi֜ym lĕ⁠halĕbi֣̇yş̌ ʼeֽţ-márĕdȯka֗y ẇ⁠lĕ⁠hási֥yr şâq֛̇⁠wò mé⁠ʻálá֖y⁠w wĕ⁠lò֥ʼ qibéֽ̇l׃"],[4,5,"וַ⁠תִּקְרָא֩ אֶסְתֵּ֨ר לַ⁠הֲתָ֜ךְ מִ⁠סָּרִיסֵ֤י הַ⁠מֶּ֨לֶךְ֙ אֲשֶׁ֣ר הֶעֱמִ֣יד לְ⁠פָנֶ֔י⁠הָ וַ⁠תְּצַוֵּ֖⁠הוּ עַֽל־מָרְדֳּכָ֑י לָ⁠דַ֥עַת מַה־זֶּ֖ה וְ⁠עַל־מַה־זֶּֽה׃","wa⁠ţi̇qĕráʼ֩ ʼesĕţé̇֨r la⁠hàţá֜kĕ mi⁠sá̇riysé֤y ha⁠mė֨lekĕ֙ ʼàşě֣r heʻèmi֣yd lĕ⁠páne֔y⁠há wa⁠ţĕ̇ẕawé֖̇⁠hẇ ʻaֽl-márĕdȯká֑y lá⁠da֥ʻaţ mah-zė֖h wĕ⁠ʻal-mah-zėֽh׃"],[4,6,"וַ⁠יֵּצֵ֥א הֲתָ֖ךְ אֶֽל־מָרְדֳּכָ֑י אֶל־רְח֣וֹב הָ⁠עִ֔יר אֲשֶׁ֖ר לִ⁠פְנֵ֥י שַֽׁעַר־הַ⁠מֶּֽלֶךְ׃","wa⁠yé̇ẕé֥ʼ hàţá֖kĕ ʼeֽl-márĕdȯká֑y ʼel-rĕẖ֣wòb há⁠ʻi֔yr ʼàşě֖r li⁠pĕné֥y şǎֽʻar-ha⁠mėֽlekĕ׃"],[4,7,"וַ⁠יַּגֶּד־ל֣⁠וֹ מָרְדֳּכַ֔י אֵ֖ת כָּל־אֲשֶׁ֣ר קָרָ֑⁠הוּ וְ⁠אֵ֣ת ׀ פָּרָשַׁ֣ת הַ⁠כֶּ֗סֶף אֲשֶׁ֨ר אָמַ֤ר הָמָן֙ לִ֠⁠שְׁקוֹל עַל־גִּנְזֵ֥י הַ⁠מֶּ֛לֶךְ ביהודיים לְ⁠אַבְּדָֽ⁠ם׃","wa⁠yȧgėd-l֣⁠wò márĕdȯka֔y ʼé֖ţ ká̇l-ʼàşě֣r qárá֑⁠hẇ wĕ⁠ʼé֣ţ ׀ pá̇ráşǎ֣ţ ha⁠kė֗sep ʼàşě֨r ʼáma֤r hámán֙ li֠⁠şĕ̌qwòl ʻal-gi̇nĕzé֥y ha⁠mė֛lekĕ byhwdyym lĕ⁠ʼabĕ̇dáֽ⁠m׃"],[4,8,"וְ⁠אֶת־פַּתְשֶׁ֣גֶן כְּתָֽב־הַ֠⁠דָּת אֲשֶׁר־נִתַּ֨ן בְּ⁠שׁוּשָׁ֤ן לְ⁠הַשְׁמִידָ⁠ם֙ נָ֣תַן ל֔⁠וֹ לְ⁠הַרְא֥וֹת אֶת־אֶסְתֵּ֖ר וּ⁠לְ⁠הַגִּ֣יד לָ֑⁠הּ וּ⁠לְ⁠צַוּ֣וֹת עָלֶ֗י⁠הָ לָ⁠ב֨וֹא אֶל־הַ⁠מֶּ֧לֶךְ לְ⁠הִֽתְחַנֶּן־ל֛⁠וֹ וּ⁠לְ⁠בַקֵּ֥שׁ מִ⁠לְּ⁠פָנָ֖י⁠ו עַל־עַמָּֽ⁠הּ׃","wĕ⁠ʼeţ-pȧţĕşě֣gen kĕ̇ţáֽb-ha֠⁠dá̇ţ ʼàşěr-niţȧ֨n bĕ̇⁠ş̌ẇşá֤̌n lĕ⁠haşĕ̌miydá⁠m֙ ná֣ţan l֔⁠wò lĕ⁠harĕʼ֥wòţ ʼeţ-ʼesĕţé֖̇r ẇ⁠lĕ⁠hagi֣̇yd lá֑⁠ḣ ẇ⁠lĕ⁠ẕaẇ֣wòţ ʻále֗y⁠há lá⁠b֨wòʼ ʼel-ha⁠mė֧lekĕ lĕ⁠hiֽţĕẖanėn-l֛⁠wò ẇ⁠lĕ⁠baqé֥̇ş̌ mi⁠lĕ̇⁠páná֖y⁠w ʻal-ʻamáֽ̇⁠ḣ׃"],[4,9,"וַ⁠יָּב֖וֹא הֲתָ֑ךְ וַ⁠יַּגֵּ֣ד לְ⁠אֶסְתֵּ֔ר אֵ֖ת דִּבְרֵ֥י מָרְדֳּכָֽי׃","wa⁠yá̇b֖wòʼ hàţá֑kĕ wa⁠yȧgé֣̇d lĕ⁠ʼesĕţé̇֔r ʼé֖ţ di̇bĕré֥y márĕdȯkáֽy׃"],[4,10,"וַ⁠תֹּ֤אמֶר אֶסְתֵּר֙ לַ⁠הֲתָ֔ךְ וַ⁠תְּצַוֵּ֖⁠הוּ אֶֽל־מָרְדֳּכָֽי׃","wa⁠ţò֤̇ʼmer ʼesĕţé̇r֙ la⁠hàţá֔kĕ wa⁠ţĕ̇ẕawé֖̇⁠hẇ ʼeֽl-márĕdȯkáֽy׃"],[4,11,"כָּל־עַבְדֵ֣י הַ⁠מֶּ֡לֶךְ וְ⁠עַם־מְדִינ֨וֹת הַ⁠מֶּ֜לֶךְ יֽוֹדְעִ֗ים אֲשֶׁ֣ר כָּל־אִ֣ישׁ וְ⁠אִשָּׁ֡ה אֲשֶׁ֣ר יָבֽוֹא־אֶל־הַ⁠מֶּלֶךְ֩ אֶל־הֶ⁠חָצֵ֨ר הַ⁠פְּנִימִ֜ית אֲשֶׁ֣ר לֹֽא־יִקָּרֵ֗א אַחַ֤ת דָּת⁠וֹ֙ לְ⁠הָמִ֔ית לְ֠⁠בַד מֵ⁠אֲשֶׁ֨ר יֽוֹשִׁיט־ל֥⁠וֹ הַ⁠מֶּ֛לֶךְ אֶת־שַׁרְבִ֥יט הַ⁠זָּהָ֖ב וְ⁠חָיָ֑ה וַ⁠אֲנִ֗י לֹ֤א נִקְרֵ֨אתי֙ לָ⁠ב֣וֹא אֶל־הַ⁠מֶּ֔לֶךְ זֶ֖ה שְׁלוֹשִׁ֥ים יֽוֹם׃","ká̇l-ʻabĕdé֣y ha⁠mė֡lekĕ wĕ⁠ʻam-mĕdiyn֨wòţ ha⁠mė֜lekĕ yֽwòdĕʻi֗ym ʼàşě֣r ká̇l-ʼi֣yş̌ wĕ⁠ʼişá̇̌֡h ʼàşě֣r yábֽwòʼ-ʼel-ha⁠mėlekĕ֩ ʼel-he⁠ẖáẕé֨r ha⁠pĕ̇niymi֜yţ ʼàşě֣r lòֽʼ-yiqá̇ré֗ʼ ʼaẖa֤ţ dá̇ţ⁠wò֙ lĕ⁠hámi֔yţ lĕ֠⁠bad mé⁠ʼàşě֨r yֽwòşǐyt-l֥⁠wò ha⁠mė֛lekĕ ʼeţ-şǎrĕbi֥yt ha⁠zá̇há֖b wĕ⁠ẖáyá֑h wa⁠ʼàni֗y lò֤ʼ niqĕré֨ʼţy֙ lá⁠b֣wòʼ ʼel-ha⁠mė֔lekĕ ze֖h şĕ̌lwòşǐ֥ym yֽwòm׃"],[4,12,"וַ⁠יַּגִּ֣ידוּ לְ⁠מָרְדֳּכָ֔י אֵ֖ת דִּבְרֵ֥י אֶסְתֵּֽר׃פ","wa⁠yȧgi֣̇ydẇ lĕ⁠márĕdȯká֔y ʼé֖ţ di̇bĕré֥y ʼesĕţéֽ̇r׃p"],[4,13,"וַ⁠יֹּ֥אמֶר מָרְדֳּכַ֖י לְ⁠הָשִׁ֣יב אֶל־אֶסְתֵּ֑ר אַל־תְּדַמִּ֣י בְ⁠נַפְשֵׁ֔⁠ךְ לְ⁠הִמָּלֵ֥ט בֵּית־הַ⁠מֶּ֖לֶךְ מִ⁠כָּל־הַ⁠יְּהוּדִֽים׃","wa⁠yò֥̇ʼmer márĕdȯka֖y lĕ⁠háşǐ֣yb ʼel-ʼesĕţé֑̇r ʼal-ţĕ̇dami֣̇y bĕ⁠napĕşé̌֔⁠kĕ lĕ⁠himá̇lé֥t bé̇yţ-ha⁠mė֖lekĕ mi⁠ká̇l-ha⁠yĕ̇hẇdiֽym׃"],[4,14,"כִּ֣י אִם־הַחֲרֵ֣שׁ תַּחֲרִישִׁי֮ בָּ⁠עֵ֣ת הַ⁠זֹּאת֒ רֶ֣וַח וְ⁠הַצָּלָ֞ה יַעֲמ֤וֹד לַ⁠יְּהוּדִים֙ מִ⁠מָּק֣וֹם אַחֵ֔ר וְ⁠אַ֥תְּ וּ⁠בֵית־אָבִ֖י⁠ךְ תֹּאבֵ֑דוּ וּ⁠מִ֣י יוֹדֵ֔עַ אִם־לְ⁠עֵ֣ת כָּ⁠זֹ֔את הִגַּ֖עַתְּ לַ⁠מַּלְכֽוּת׃","ki֣̇y ʼim-haẖàré֣ş̌ ţȧẖàriyşǐy֮ bá̇⁠ʻé֣ţ ha⁠zò̇ʼţ֒ re֣waẖ wĕ⁠haẕá̇lá֞h yaʻàm֤wòd la⁠yĕ̇hẇdiym֙ mi⁠má̇q֣wòm ʼaẖé֔r wĕ⁠ʼa֥ţĕ̇ ẇ⁠béyţ-ʼábi֖y⁠kĕ ţò̇ʼbé֑dẇ ẇ⁠mi֣y ywòdé֔ʻa ʼim-lĕ⁠ʻé֣ţ ká̇⁠zò֔ʼţ higȧ֖ʻaţĕ̇ la⁠mȧlĕkֽẇţ׃"],[4,15,"וַ⁠תֹּ֥אמֶר אֶסְתֵּ֖ר לְ⁠הָשִׁ֥יב אֶֽל־מָרְדֳּכָֽי׃","wa⁠ţò֥̇ʼmer ʼesĕţé֖̇r lĕ⁠háşǐ֥yb ʼeֽl-márĕdȯkáֽy׃"],[4,16,"לֵךְ֩ כְּנ֨וֹס אֶת־כָּל־הַ⁠יְּהוּדִ֜ים הַֽ⁠נִּמְצְאִ֣ים בְּ⁠שׁוּשָׁ֗ן וְ⁠צ֣וּמוּ עָ֠לַ⁠י וְ⁠אַל־תֹּאכְל֨וּ וְ⁠אַל־תִּשְׁתּ֜וּ שְׁלֹ֤שֶׁת יָמִים֙ לַ֣יְלָה וָ⁠י֔וֹם גַּם־אֲנִ֥י וְ⁠נַעֲרֹתַ֖⁠י אָצ֣וּם כֵּ֑ן וּ⁠בְ⁠כֵ֞ן אָב֤וֹא אֶל־הַ⁠מֶּ֨לֶךְ֙ אֲשֶׁ֣ר לֹֽא־כַ⁠דָּ֔ת וְ⁠כַ⁠אֲשֶׁ֥ר אָבַ֖דְתִּי אָבָֽדְתִּי׃","lékĕ֩ kĕ̇n֨wòs ʼeţ-ká̇l-ha⁠yĕ̇hẇdi֜ym haֽ⁠ni̇mĕẕĕʼi֣ym bĕ̇⁠ş̌ẇşá̌֗n wĕ⁠ẕ֣ẇmẇ ʻá֠la⁠y wĕ⁠ʼal-ţò̇ʼkĕl֨ẇ wĕ⁠ʼal-ţi̇şĕ̌ţ̇֜ẇ şĕ̌lò֤şěţ yámiym֙ la֣yĕláh wá⁠y֔wòm gȧm-ʼàni֥y wĕ⁠naʻàròţa֖⁠y ʼáẕ֣ẇm ké֑̇n ẇ⁠bĕ⁠ké֞n ʼáb֤wòʼ ʼel-ha⁠mė֨lekĕ֙ ʼàşě֣r lòֽʼ-ka⁠dá̇֔ţ wĕ⁠ka⁠ʼàşě֥r ʼába֖dĕţi̇y ʼábáֽdĕţi̇y׃"],[4,17,"וַֽ⁠יַּעֲבֹ֖ר מָרְדֳּכָ֑י וַ⁠יַּ֕עַשׂ כְּ⁠כֹ֛ל אֲשֶׁר־צִוְּתָ֥ה עָלָ֖י⁠ו אֶסְתֵּֽר׃ס","waֽ⁠yȧʻàbò֖r márĕdȯká֑y wa⁠yȧ֕ʻaş̂ kĕ̇⁠kò֛l ʼàşěr-ẕiwĕ̇ţá֥h ʻálá֖y⁠w ʼesĕţéֽ̇r׃s"],[5,1,"וַ⁠יְהִ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֗י וַ⁠תִּלְבַּ֤שׁ אֶסְתֵּר֙ מַלְכ֔וּת וַֽ⁠תַּעֲמֹ֞ד בַּ⁠חֲצַ֤ר בֵּית־הַ⁠מֶּ֨לֶךְ֙ הַ⁠פְּנִימִ֔ית נֹ֖כַח בֵּ֣ית הַ⁠מֶּ֑לֶךְ וְ֠⁠הַ⁠מֶּלֶךְ יוֹשֵׁ֞ב עַל־כִּסֵּ֤א מַלְכוּת⁠וֹ֙ בְּ⁠בֵ֣ית הַ⁠מַּלְכ֔וּת נֹ֖כַח פֶּ֥תַח הַ⁠בָּֽיִת׃","wa⁠yĕhi֣y ׀ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֗y wa⁠ţi̇lĕbȧ֤ş̌ ʼesĕţé̇r֙ malĕk֔ẇţ waֽ⁠ţȧʻàmò֞d bȧ⁠ẖàẕa֤r bé̇yţ-ha⁠mė֨lekĕ֙ ha⁠pĕ̇niymi֔yţ nò֖kaẖ bé֣̇yţ ha⁠mė֑lekĕ wĕ֠⁠ha⁠mėlekĕ ywòşé̌֞b ʻal-ki̇sé֤̇ʼ malĕkẇţ⁠wò֙ bĕ̇⁠bé֣yţ ha⁠mȧlĕk֔ẇţ nò֖kaẖ pė֥ţaẖ ha⁠báֽ̇yiţ׃"],[5,2,"וַ⁠יְהִי֩ כִ⁠רְא֨וֹת הַ⁠מֶּ֜לֶךְ אֶת־אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֗ה עֹמֶ֨דֶת֙ בֶּֽ⁠חָצֵ֔ר נָשְׂאָ֥ה חֵ֖ן בְּ⁠עֵינָ֑י⁠ו וַ⁠יּ֨וֹשֶׁט הַ⁠מֶּ֜לֶךְ לְ⁠אֶסְתֵּ֗ר אֶת־שַׁרְבִ֤יט הַ⁠זָּהָב֙ אֲשֶׁ֣ר בְּ⁠יָד֔⁠וֹ וַ⁠תִּקְרַ֣ב אֶסְתֵּ֔ר וַ⁠תִּגַּ֖ע בְּ⁠רֹ֥אשׁ הַ⁠שַּׁרְבִֽיט׃ס","wa⁠yĕhiy֩ ki⁠rĕʼ֨wòţ ha⁠mė֜lekĕ ʼeţ-ʼesĕţé֣̇r ha⁠mȧlĕká̇֗h ʻòme֨deţ֙ bėֽ⁠ẖáẕé֔r náşĕ̂ʼá֥h ẖé֖n bĕ̇⁠ʻéyná֑y⁠w wa⁠ẏ֨wòşět ha⁠mė֜lekĕ lĕ⁠ʼesĕţé̇֗r ʼeţ-şǎrĕbi֤yt ha⁠zá̇háb֙ ʼàşě֣r bĕ̇⁠yád֔⁠wò wa⁠ţi̇qĕra֣b ʼesĕţé̇֔r wa⁠ţi̇gȧ֖ʻ bĕ̇⁠rò֥ʼş̌ ha⁠şȧ̌rĕbiֽyt׃s"],[5,3,"וַ⁠יֹּ֤אמֶר לָ⁠הּ֙ הַ⁠מֶּ֔לֶךְ מַה־לָּ֖⁠ךְ אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֑ה וּ⁠מַה־בַּקָּשָׁתֵ֛⁠ךְ עַד־חֲצִ֥י הַ⁠מַּלְכ֖וּת וְ⁠יִנָּ֥תֵֽן לָֽ⁠ךְ׃","wa⁠yò֤̇ʼmer lá⁠ḣ֙ ha⁠mė֔lekĕ mah-lá֖̇⁠kĕ ʼesĕţé֣̇r ha⁠mȧlĕká֑̇h ẇ⁠mah-bȧqá̇şá̌ţé֛⁠kĕ ʻad-ẖàẕi֥y ha⁠mȧlĕk֖ẇţ wĕ⁠yiná֥̇ţéֽn láֽ⁠kĕ׃"],[5,4,"וַ⁠תֹּ֣אמֶר אֶסְתֵּ֔ר אִם־עַל־הַ⁠מֶּ֖לֶךְ ט֑וֹב יָב֨וֹא הַ⁠מֶּ֤לֶךְ וְ⁠הָמָן֙ הַ⁠יּ֔וֹם אֶל־הַ⁠מִּשְׁתֶּ֖ה אֲשֶׁר־עָשִׂ֥יתִי לֽ⁠וֹ׃","wa⁠ţò֣̇ʼmer ʼesĕţé̇֔r ʼim-ʻal-ha⁠mė֖lekĕ t֑wòb yáb֨wòʼ ha⁠mė֤lekĕ wĕ⁠hámán֙ ha⁠ẏ֔wòm ʼel-ha⁠mi̇şĕ̌ţė֖h ʼàşěr-ʻáşî֥yţiy lֽ⁠wò׃"],[5,5,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ מַהֲרוּ֙ אֶת־הָמָ֔ן לַ⁠עֲשׂ֖וֹת אֶת־דְּבַ֣ר אֶסְתֵּ֑ר וַ⁠יָּבֹ֤א הַ⁠מֶּ֨לֶךְ֙ וְ⁠הָמָ֔ן אֶל־הַ⁠מִּשְׁתֶּ֖ה אֲשֶׁר־עָשְׂתָ֥ה אֶסְתֵּֽר׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ mahàrẇ֙ ʼeţ-hámá֔n la⁠ʻàş֖̂wòţ ʼeţ-dĕ̇ba֣r ʼesĕţé֑̇r wa⁠yá̇bò֤ʼ ha⁠mė֨lekĕ֙ wĕ⁠hámá֔n ʼel-ha⁠mi̇şĕ̌ţė֖h ʼàşěr-ʻáşĕ̂ţá֥h ʼesĕţéֽ̇r׃"],[5,6,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֤לֶךְ לְ⁠אֶסְתֵּר֙ בְּ⁠מִשְׁתֵּ֣ה הַ⁠יַּ֔יִן מַה־שְּׁאֵלָתֵ֖⁠ךְ וְ⁠יִנָּ֣תֵֽן לָ֑⁠ךְ וּ⁠מַה־בַּקָּשָׁתֵ֛⁠ךְ עַד־חֲצִ֥י הַ⁠מַּלְכ֖וּת וְ⁠תֵעָֽשׂ׃","wa⁠yò̇֨ʼmer ha⁠mė֤lekĕ lĕ⁠ʼesĕţé̇r֙ bĕ̇⁠mişĕ̌ţé֣̇h ha⁠yȧ֔yin mah-şĕ̇̌ʼéláţé֖⁠kĕ wĕ⁠yiná֣̇ţéֽn lá֑⁠kĕ ẇ⁠mah-bȧqá̇şá̌ţé֛⁠kĕ ʻad-ẖàẕi֥y ha⁠mȧlĕk֖ẇţ wĕ⁠ţéʻáֽş̂׃"],[5,7,"וַ⁠תַּ֥עַן אֶסְתֵּ֖ר וַ⁠תֹּאמַ֑ר שְׁאֵלָתִ֖⁠י וּ⁠בַקָּשָׁתִֽ⁠י׃","wa⁠ţȧ֥ʻan ʼesĕţé֖̇r wa⁠ţò̇ʼma֑r şĕ̌ʼéláţi֖⁠y ẇ⁠baqá̇şá̌ţiֽ⁠y׃"],[5,8,"אִם־מָצָ֨אתִי חֵ֜ן בְּ⁠עֵינֵ֣י הַ⁠מֶּ֗לֶךְ וְ⁠אִם־עַל־הַ⁠מֶּ֨לֶךְ֙ ט֔וֹב לָ⁠תֵת֙ אֶת־שְׁאֵ֣לָתִ֔⁠י וְ⁠לַ⁠עֲשׂ֖וֹת אֶת־בַּקָּשָׁתִ֑⁠י יָב֧וֹא הַ⁠מֶּ֣לֶךְ וְ⁠הָמָ֗ן אֶל־הַ⁠מִּשְׁתֶּה֙ אֲשֶׁ֣ר אֶֽעֱשֶׂ֣ה לָ⁠הֶ֔ם וּ⁠מָחָ֥ר אֶֽעֱשֶׂ֖ה כִּ⁠דְבַ֥ר הַ⁠מֶּֽלֶךְ׃","ʼim-máẕá֨ʼţiy ẖé֜n bĕ̇⁠ʻéyné֣y ha⁠mė֗lekĕ wĕ⁠ʼim-ʻal-ha⁠mė֨lekĕ֙ t֔wòb lá⁠ţéţ֙ ʼeţ-şĕ̌ʼé֣láţi֔⁠y wĕ⁠la⁠ʻàş֖̂wòţ ʼeţ-bȧqá̇şá̌ţi֑⁠y yáb֧wòʼ ha⁠mė֣lekĕ wĕ⁠hámá֗n ʼel-ha⁠mi̇şĕ̌ţėh֙ ʼàşě֣r ʼeֽʻèşê֣h lá⁠he֔m ẇ⁠máẖá֥r ʼeֽʻèşê֖h ki̇⁠dĕba֥r ha⁠mėֽlekĕ׃"],[5,9,"וַ⁠יֵּצֵ֤א הָמָן֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא שָׂמֵ֖חַ וְ⁠ט֣וֹב לֵ֑ב וְ⁠כִ⁠רְאוֹת֩ הָמָ֨ן אֶֽת־מָרְדֳּכַ֜י בְּ⁠שַׁ֣עַר הַ⁠מֶּ֗לֶךְ וְ⁠לֹא־קָם֙ וְ⁠לֹא־זָ֣ע מִמֶּ֔⁠נּוּ וַ⁠יִּמָּלֵ֥א הָמָ֛ן עַֽל־מָרְדֳּכַ֖י חֵמָֽה׃","wa⁠yé̇ẕé֤ʼ hámán֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ şá̂mé֖ẖa wĕ⁠t֣wòb lé֑b wĕ⁠ki⁠rĕʼwòţ֩ hámá֨n ʼeֽţ-márĕdȯka֜y bĕ̇⁠şǎ֣ʻar ha⁠mė֗lekĕ wĕ⁠lòʼ-qám֙ wĕ⁠lòʼ-zá֣ʻ mimė֔⁠ṅẇ wa⁠yi̇má̇lé֥ʼ hámá֛n ʻaֽl-márĕdȯka֖y ẖémáֽh׃"],[5,10,"וַ⁠יִּתְאַפַּ֣ק הָמָ֔ן וַ⁠יָּב֖וֹא אֶל־בֵּית֑⁠וֹ וַ⁠יִּשְׁלַ֛ח וַ⁠יָּבֵ֥א אֶת־אֹהֲבָ֖י⁠ו וְ⁠אֶת־זֶ֥רֶשׁ אִשְׁתּֽ⁠וֹ׃","wa⁠yi̇ţĕʼapȧ֣q hámá֔n wa⁠yá̇b֖wòʼ ʼel-bé̇yţ֑⁠wò wa⁠yi̇şĕ̌la֛ẖ wa⁠yá̇bé֥ʼ ʼeţ-ʼòhàbá֖y⁠w wĕ⁠ʼeţ-ze֥reş̌ ʼişĕ̌ţֽ̇⁠wò׃"],[5,11,"וַ⁠יְסַפֵּ֨ר לָ⁠הֶ֥ם הָמָ֛ן אֶת־כְּב֥וֹד עָשְׁר֖⁠וֹ וְ⁠רֹ֣ב בָּנָ֑י⁠ו וְ⁠אֵת֩ כָּל־אֲשֶׁ֨ר גִּדְּל֤⁠וֹ הַ⁠מֶּ֨לֶךְ֙ וְ⁠אֵ֣ת אֲשֶׁ֣ר נִשְּׂא֔⁠וֹ עַל־הַ⁠שָּׂרִ֖ים וְ⁠עַבְדֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yĕsapé̇֨r lá⁠he֥m hámá֛n ʼeţ-kĕ̇b֥wòd ʻáşĕ̌r֖⁠wò wĕ⁠rò֣b bá̇ná֑y⁠w wĕ⁠ʼéţ֩ ká̇l-ʼàşě֨r gi̇dĕ̇l֤⁠wò ha⁠mė֨lekĕ֙ wĕ⁠ʼé֣ţ ʼàşě֣r nişĕ̇̂ʼ֔⁠wò ʻal-ha⁠şá̇̂ri֖ym wĕ⁠ʻabĕdé֥y ha⁠mėֽlekĕ׃"],[5,12,"וַ⁠יֹּאמֶר֮ הָמָן֒ אַ֣ף לֹא־הֵבִיאָה֩ אֶסְתֵּ֨ר הַ⁠מַּלְכָּ֧ה עִם־הַ⁠מֶּ֛לֶךְ אֶל־הַ⁠מִּשְׁתֶּ֥ה אֲשֶׁר־עָשָׂ֖תָה כִּ֣י אִם־אוֹתִ֑⁠י וְ⁠גַם־לְ⁠מָחָ֛ר אֲנִ֥י קָֽרוּא־לָ֖⁠הּ עִם־הַ⁠מֶּֽלֶךְ׃","wa⁠yò̇ʼmer֮ hámán֒ ʼa֣p lòʼ-hébiyʼáh֩ ʼesĕţé̇֨r ha⁠mȧlĕká֧̇h ʻim-ha⁠mė֛lekĕ ʼel-ha⁠mi̇şĕ̌ţė֥h ʼàşěr-ʻáşá֖̂ţáh ki֣̇y ʼim-ʼwòţi֑⁠y wĕ⁠gam-lĕ⁠máẖá֛r ʼàni֥y qáֽrẇʼ-lá֖⁠ḣ ʻim-ha⁠mėֽlekĕ׃"],[5,13,"וְ⁠כָל־זֶ֕ה אֵינֶ֥⁠נּוּ שֹׁוֶ֖ה לִ֑⁠י בְּ⁠כָל־עֵ֗ת אֲשֶׁ֨ר אֲנִ֤י רֹאֶה֙ אֶת־מָרְדֳּכַ֣י הַ⁠יְּהוּדִ֔י יוֹשֵׁ֖ב בְּ⁠שַׁ֥עַר הַ⁠מֶּֽלֶךְ׃","wĕ⁠kál-ze֕h ʼéyne֥⁠ṅẇ şò̌we֖h li֑⁠y bĕ̇⁠kál-ʻé֗ţ ʼàşě֨r ʼàni֤y ròʼeh֙ ʼeţ-márĕdȯka֣y ha⁠yĕ̇hẇdi֔y ywòşé֖̌b bĕ̇⁠şǎ֥ʻar ha⁠mėֽlekĕ׃"],[5,14,"וַ⁠תֹּ֣אמֶר ל⁠וֹ֩ זֶ֨רֶשׁ אִשְׁתּ֜⁠וֹ וְ⁠כָל־אֹֽהֲבָ֗י⁠ו יַֽעֲשׂוּ־עֵץ֮ גָּבֹ֣הַּ חֲמִשִּׁ֣ים אַמָּה֒ וּ⁠בַ⁠בֹּ֣קֶר ׀ אֱמֹ֣ר לַ⁠מֶּ֗לֶךְ וְ⁠יִתְל֤וּ אֶֽת־מָרְדֳּכַי֙ עָלָ֔י⁠ו וּ⁠בֹֽא־עִם־הַ⁠מֶּ֥לֶךְ אֶל הַ⁠מִּשְׁתֶּ֖ה שָׂמֵ֑חַ וַ⁠יִּיטַ֧ב הַ⁠דָּבָ֛ר לִ⁠פְנֵ֥י הָמָ֖ן וַ⁠יַּ֥עַשׂ הָ⁠עֵֽץ׃פ","wa⁠ţò֣̇ʼmer l⁠wò֩ ze֨reş̌ ʼişĕ̌ţ̇֜⁠wò wĕ⁠kál-ʼòֽhàbá֗y⁠w yaֽʻàş̂ẇ-ʻéẕ֮ gá̇bò֣hȧ ẖàmişi֣̇̌ym ʼamá̇h֒ ẇ⁠ba⁠bò֣̇qer ׀ ʼèmò֣r la⁠mė֗lekĕ wĕ⁠yiţĕl֤ẇ ʼeֽţ-márĕdȯkay֙ ʻálá֔y⁠w ẇ⁠bòֽʼ-ʻim-ha⁠mė֥lekĕ ʼel ha⁠mi̇şĕ̌ţė֖h şá̂mé֑ẖa wa⁠yi̇yta֧b ha⁠dá̇bá֛r li⁠pĕné֥y hámá֖n wa⁠yȧ֥ʻaş̂ há⁠ʻéֽẕ׃p"],[6,1,"בַּ⁠לַּ֣יְלָה הַ⁠ה֔וּא נָדְדָ֖ה שְׁנַ֣ת הַ⁠מֶּ֑לֶךְ וַ⁠יֹּ֗אמֶר לְ⁠הָבִ֞יא אֶת־סֵ֤פֶר הַ⁠זִּכְרֹנוֹת֙ דִּבְרֵ֣י הַ⁠יָּמִ֔ים וַ⁠יִּהְי֥וּ נִקְרָאִ֖ים לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","bȧ⁠lȧ֣yĕláh ha⁠h֔ẇʼ nádĕdá֖h şĕ̌na֣ţ ha⁠mė֑lekĕ wa⁠yò̇֗ʼmer lĕ⁠hábi֞yʼ ʼeţ-sé֤per ha⁠zi̇kĕrònwòţ֙ di̇bĕré֣y ha⁠yá̇mi֔ym wa⁠yi̇hĕy֥ẇ niqĕráʼi֖ym li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[6,2,"וַ⁠יִּמָּצֵ֣א כָת֗וּב אֲשֶׁר֩ הִגִּ֨יד מָרְדֳּכַ֜י עַל־בִּגְתָ֣נָא וָ⁠תֶ֗רֶשׁ שְׁנֵי֙ סָרִיסֵ֣י הַ⁠מֶּ֔לֶךְ מִ⁠שֹּׁמְרֵ֖י הַ⁠סַּ֑ף אֲשֶׁ֤ר בִּקְשׁוּ֙ לִ⁠שְׁלֹ֣חַ יָ֔ד בַּ⁠מֶּ֖לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃","wa⁠yi̇má̇ẕé֣ʼ káţ֗ẇb ʼàşěr֩ higi̇֨yd márĕdȯka֜y ʻal-bi̇gĕţá֣náʼ wá⁠ţe֗reş̌ şĕ̌néy֙ sáriysé֣y ha⁠mė֔lekĕ mi⁠şò̇̌mĕré֖y ha⁠sȧ֑p ʼàşě֤r bi̇qĕş̌ẇ֙ li⁠şĕ̌lò֣ẖa yá֔d bȧ⁠mė֖lekĕ ʼàẖaşĕ̌wérֽwòş̌׃"],[6,3,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ מַֽה־נַּעֲשָׂ֞ה יְקָ֧ר וּ⁠גְדוּלָּ֛ה לְ⁠מָרְדֳּכַ֖י עַל־זֶ֑ה וַ⁠יֹּ֨אמְר֜וּ נַעֲרֵ֤י הַ⁠מֶּ֨לֶךְ֙ מְשָׁ֣רְתָ֔י⁠ו לֹא־נַעֲשָׂ֥ה עִמּ֖⁠וֹ דָּבָֽר׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ maֽh-nȧʻàşá̂֞h yĕqá֧r ẇ⁠gĕdẇlá֛̇h lĕ⁠márĕdȯka֖y ʻal-ze֑h wa⁠yò̇֨ʼmĕr֜ẇ naʻàré֤y ha⁠mė֨lekĕ֙ mĕşá֣̌rĕţá֔y⁠w lòʼ-naʻàşá֥̂h ʻiṁ֖⁠wò dá̇báֽr׃"],[6,4,"וַ⁠יֹּ֥אמֶר הַ⁠מֶּ֖לֶךְ מִ֣י בֶ⁠חָצֵ֑ר וְ⁠הָמָ֣ן בָּ֗א לַ⁠חֲצַ֤ר בֵּית־הַ⁠מֶּ֨לֶךְ֙ הַ⁠חִ֣יצוֹנָ֔ה לֵ⁠אמֹ֣ר לַ⁠מֶּ֔לֶךְ לִ⁠תְלוֹת֙ אֶֽת־מָרְדֳּכַ֔י עַל־הָ⁠עֵ֖ץ אֲשֶׁר־הֵכִ֥ין לֽ⁠וֹ׃","wa⁠yò֥̇ʼmer ha⁠mė֖lekĕ mi֣y be⁠ẖáẕé֑r wĕ⁠hámá֣n bá̇֗ʼ la⁠ẖàẕa֤r bé̇yţ-ha⁠mė֨lekĕ֙ ha⁠ẖi֣yẕwòná֔h lé⁠ʼmò֣r la⁠mė֔lekĕ li⁠ţĕlwòţ֙ ʼeֽţ-márĕdȯka֔y ʻal-há⁠ʻé֖ẕ ʼàşěr-héki֥yn lֽ⁠wò׃"],[6,5,"וַ⁠יֹּ֨אמְר֜וּ נַעֲרֵ֤י הַ⁠מֶּ֨לֶךְ֙ אֵלָ֔י⁠ו הִנֵּ֥ה הָמָ֖ן עֹמֵ֣ד בֶּ⁠חָצֵ֑ר וַ⁠יֹּ֥אמֶר הַ⁠מֶּ֖לֶךְ יָבֽוֹא׃","wa⁠yò̇֨ʼmĕr֜ẇ naʻàré֤y ha⁠mė֨lekĕ֙ ʼélá֔y⁠w hiné֥̇h hámá֖n ʻòmé֣d bė⁠ẖáẕé֑r wa⁠yò֥̇ʼmer ha⁠mė֖lekĕ yábֽwòʼ׃"],[6,6,"וַ⁠יָּבוֹא֮ הָמָן֒ וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ הַ⁠מֶּ֔לֶךְ מַה־לַ⁠עֲשׂ֕וֹת בָּ⁠אִ֕ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֣ץ בִּ⁠יקָר֑⁠וֹ וַ⁠יֹּ֤אמֶר הָמָן֙ בְּ⁠לִבּ֔⁠וֹ לְ⁠מִ֞י יַחְפֹּ֥ץ הַ⁠מֶּ֛לֶךְ לַ⁠עֲשׂ֥וֹת יְקָ֖ר יוֹתֵ֥ר מִמֶּֽ⁠נִּי׃","wa⁠yá̇bwòʼ֮ hámán֒ wa⁠yò֤̇ʼmer l⁠wò֙ ha⁠mė֔lekĕ mah-la⁠ʻàş̂֕wòţ bá̇⁠ʼi֕yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֣ẕ bi̇⁠yqár֑⁠wò wa⁠yò֤̇ʼmer hámán֙ bĕ̇⁠liḃ֔⁠wò lĕ⁠mi֞y yaẖĕpò֥̇ẕ ha⁠mė֛lekĕ la⁠ʻàş֥̂wòţ yĕqá֖r ywòţé֥r mimėֽ⁠ni̇y׃"],[6,7,"וַ⁠יֹּ֥אמֶר הָמָ֖ן אֶל־הַ⁠מֶּ֑לֶךְ אִ֕ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֥ץ בִּ⁠יקָרֽ⁠וֹ׃","wa⁠yò֥̇ʼmer hámá֖n ʼel-ha⁠mė֑lekĕ ʼi֕yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֥ẕ bi̇⁠yqárֽ⁠wò׃"],[6,8,"יָבִ֨יאוּ֙ לְב֣וּשׁ מַלְכ֔וּת אֲשֶׁ֥ר לָֽבַשׁ־בּ֖⁠וֹ הַ⁠מֶּ֑לֶךְ וְ⁠ס֗וּס אֲשֶׁ֨ר רָכַ֤ב עָלָי⁠ו֙ הַ⁠מֶּ֔לֶךְ וַ⁠אֲשֶׁ֥ר נִתַּ֛ן כֶּ֥תֶר מַלְכ֖וּת בְּ⁠רֹאשֽׁ⁠וֹ׃","yábi֨yʼẇ֙ lĕb֣ẇş̌ malĕk֔ẇţ ʼàşě֥r láֽbaş̌-ḃ֖⁠wò ha⁠mė֑lekĕ wĕ⁠s֗ẇs ʼàşě֨r ráka֤b ʻáláy⁠w֙ ha⁠mė֔lekĕ wa⁠ʼàşě֥r niţȧ֛n kė֥ţer malĕk֖ẇţ bĕ̇⁠ròʼşֽ̌⁠wò׃"],[6,9,"וְ⁠נָת֨וֹן הַ⁠לְּב֜וּשׁ וְ⁠הַ⁠סּ֗וּס עַל־יַד־אִ֞ישׁ מִ⁠שָּׂרֵ֤י הַ⁠מֶּ֨לֶךְ֙ הַֽ⁠פַּרְתְּמִ֔ים וְ⁠הִלְבִּ֨ישׁוּ֙ אֶת־הָ⁠אִ֔ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֣ץ בִּֽ⁠יקָר֑⁠וֹ וְ⁠הִרְכִּיבֻ֤⁠הוּ עַל־הַ⁠סּוּס֙ בִּ⁠רְח֣וֹב הָ⁠עִ֔יר וְ⁠קָרְא֣וּ לְ⁠פָנָ֔י⁠ו כָּ֚כָה יֵעָשֶׂ֣ה לָ⁠אִ֔ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֥ץ בִּ⁠יקָרֽ⁠וֹ׃","wĕ⁠náţ֨wòn ha⁠lĕ̇b֜ẇş̌ wĕ⁠ha⁠ṡ֗ẇs ʻal-yad-ʼi֞yş̌ mi⁠şá̇̂ré֤y ha⁠mė֨lekĕ֙ haֽ⁠pȧrĕţĕ̇mi֔ym wĕ⁠hilĕbi̇֨yş̌ẇ֙ ʼeţ-há⁠ʼi֔yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֣ẕ biֽ̇⁠yqár֑⁠wò wĕ⁠hirĕki̇ybu֤⁠hẇ ʻal-ha⁠ṡẇs֙ bi̇⁠rĕẖ֣wòb há⁠ʻi֔yr wĕ⁠qárĕʼ֣ẇ lĕ⁠páná֔y⁠w ká֚̇káh yéʻáşê֣h lá⁠ʼi֔yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֥ẕ bi̇⁠yqárֽ⁠wò׃"],[6,10,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ לְ⁠הָמָ֗ן מַ֠הֵר קַ֣ח אֶת־הַ⁠לְּב֤וּשׁ וְ⁠אֶת־הַ⁠סּוּס֙ כַּ⁠אֲשֶׁ֣ר דִּבַּ֔רְתָּ וַֽ⁠עֲשֵׂה־כֵן֙ לְ⁠מָרְדֳּכַ֣י הַ⁠יְּהוּדִ֔י הַ⁠יּוֹשֵׁ֖ב בְּ⁠שַׁ֣עַר הַ⁠מֶּ֑לֶךְ אַל־תַּפֵּ֣ל דָּבָ֔ר מִ⁠כֹּ֖ל אֲשֶׁ֥ר דִּבַּֽרְתָּ׃","wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ lĕ⁠hámá֗n ma֠hér qa֣ẖ ʼeţ-ha⁠lĕ̇b֤ẇş̌ wĕ⁠ʼeţ-ha⁠ṡẇs֙ kȧ⁠ʼàşě֣r di̇bȧ֔rĕţá̇ waֽ⁠ʻàşé̂h-kén֙ lĕ⁠márĕdȯka֣y ha⁠yĕ̇hẇdi֔y ha⁠ẏwòşé֖̌b bĕ̇⁠şǎ֣ʻar ha⁠mė֑lekĕ ʼal-ţȧpé֣̇l dá̇bá֔r mi⁠kò֖̇l ʼàşě֥r di̇bȧֽrĕţá̇׃"],[6,11,"וַ⁠יִּקַּ֤ח הָמָן֙ אֶת־הַ⁠לְּב֣וּשׁ וְ⁠אֶת־הַ⁠סּ֔וּס וַ⁠יַּלְבֵּ֖שׁ אֶֽת־מָרְדֳּכָ֑י וַ⁠יַּרְכִּיבֵ֨⁠הוּ֙ בִּ⁠רְח֣וֹב הָ⁠עִ֔יר וַ⁠יִּקְרָ֣א לְ⁠פָנָ֔י⁠ו כָּ֚כָה יֵעָשֶׂ֣ה לָ⁠אִ֔ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֥ץ בִּ⁠יקָרֽ⁠וֹ׃","wa⁠yi̇qȧ֤ẖ hámán֙ ʼeţ-ha⁠lĕ̇b֣ẇş̌ wĕ⁠ʼeţ-ha⁠ṡ֔ẇs wa⁠yȧlĕbé֖̇ş̌ ʼeֽţ-márĕdȯká֑y wa⁠yȧrĕki̇ybé֨⁠hẇ֙ bi̇⁠rĕẖ֣wòb há⁠ʻi֔yr wa⁠yi̇qĕrá֣ʼ lĕ⁠páná֔y⁠w ká֚̇káh yéʻáşê֣h lá⁠ʼi֔yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֥ẕ bi̇⁠yqárֽ⁠wò׃"],[6,12,"וַ⁠יָּ֥שָׁב מָרְדֳּכַ֖י אֶל־שַׁ֣עַר הַ⁠מֶּ֑לֶךְ וְ⁠הָמָן֙ נִדְחַ֣ף אֶל־בֵּית֔⁠וֹ אָבֵ֖ל וַ⁠חֲפ֥וּי רֹֽאשׁ׃","wa⁠yá֥̇şá̌b márĕdȯka֖y ʼel-şǎ֣ʻar ha⁠mė֑lekĕ wĕ⁠hámán֙ nidĕẖa֣p ʼel-bé̇yţ֔⁠wò ʼábé֖l wa⁠ẖàp֥ẇy ròֽʼş̌׃"],[6,13,"וַ⁠יְסַפֵּ֨ר הָמָ֜ן לְ⁠זֶ֤רֶשׁ אִשְׁתּ⁠וֹ֙ וּ⁠לְ⁠כָל־אֹ֣הֲבָ֔י⁠ו אֵ֖ת כָּל־אֲשֶׁ֣ר קָרָ֑⁠הוּ וַ⁠יֹּ֩אמְרוּ֩ ל֨⁠וֹ חֲכָמָ֜י⁠ו וְ⁠זֶ֣רֶשׁ אִשְׁתּ֗⁠וֹ אִ֣ם מִ⁠זֶּ֣רַע הַ⁠יְּהוּדִ֡ים מָרְדֳּכַ֞י אֲשֶׁר֩ הַחִלּ֨וֹתָ לִ⁠נְפֹּ֤ל לְ⁠פָנָי⁠ו֙ לֹא־תוּכַ֣ל ל֔⁠וֹ כִּֽי־נָפ֥וֹל תִּפּ֖וֹל לְ⁠פָנָֽי⁠ו׃","wa⁠yĕsapé̇֨r hámá֜n lĕ⁠ze֤reş̌ ʼişĕ̌ţ̇⁠wò֙ ẇ⁠lĕ⁠kál-ʼò֣hàbá֔y⁠w ʼé֖ţ ká̇l-ʼàşě֣r qárá֑⁠hẇ wa⁠yò̇֩ʼmĕrẇ֩ l֨⁠wò ẖàkámá֜y⁠w wĕ⁠ze֣reş̌ ʼişĕ̌ţ̇֗⁠wò ʼi֣m mi⁠zė֣raʻ ha⁠yĕ̇hẇdi֡ym márĕdȯka֞y ʼàşěr֩ haẖil̇֨wòţá li⁠nĕpò֤̇l lĕ⁠pánáy⁠w֙ lòʼ-ţẇka֣l l֔⁠wò kiֽ̇y-náp֥wòl ţi̇ṗ֖wòl lĕ⁠pánáֽy⁠w׃"],[6,14,"עוֹדָ⁠ם֙ מְדַבְּרִ֣ים עִמּ֔⁠וֹ וְ⁠סָרִיסֵ֥י הַ⁠מֶּ֖לֶךְ הִגִּ֑יעוּ וַ⁠יַּבְהִ֨לוּ֙ לְ⁠הָבִ֣יא אֶת־הָמָ֔ן אֶל־הַ⁠מִּשְׁתֶּ֖ה אֲשֶׁר־עָשְׂתָ֥ה אֶסְתֵּֽר׃","ʻwòdá⁠m֙ mĕdabĕ̇ri֣ym ʻiṁ֔⁠wò wĕ⁠sáriysé֥y ha⁠mė֖lekĕ higi֑̇yʻẇ wa⁠yȧbĕhi֨lẇ֙ lĕ⁠hábi֣yʼ ʼeţ-hámá֔n ʼel-ha⁠mi̇şĕ̌ţė֖h ʼàşěr-ʻáşĕ̂ţá֥h ʼesĕţéֽ̇r׃"],[7,1,"וַ⁠יָּבֹ֤א הַ⁠מֶּ֨לֶךְ֙ וְ⁠הָמָ֔ן לִ⁠שְׁתּ֖וֹת עִם־אֶסְתֵּ֥ר הַ⁠מַּלְכָּֽה׃","wa⁠yá̇bò֤ʼ ha⁠mė֨lekĕ֙ wĕ⁠hámá֔n li⁠şĕ̌ţ֖̇wòţ ʻim-ʼesĕţé֥̇r ha⁠mȧlĕkáֽ̇h׃"],[7,2,"וַ⁠יֹּאמֶר֩ הַ⁠מֶּ֨לֶךְ לְ⁠אֶסְתֵּ֜ר גַּ֣ם בַּ⁠יּ֤וֹם הַ⁠שֵּׁנִי֙ בְּ⁠מִשְׁתֵּ֣ה הַ⁠יַּ֔יִן מַה־שְּׁאֵלָתֵ֛⁠ךְ אֶסְתֵּ֥ר הַ⁠מַּלְכָּ֖ה וְ⁠תִנָּ֣תֵֽן לָ֑⁠ךְ וּ⁠מַה־בַּקָּשָׁתֵ֛⁠ךְ עַד־חֲצִ֥י הַ⁠מַּלְכ֖וּת וְ⁠תֵעָֽשׂ׃","wa⁠yò̇ʼmer֩ ha⁠mė֨lekĕ lĕ⁠ʼesĕţé̇֜r gȧ֣m bȧ⁠ẏ֤wòm ha⁠şé̇̌niy֙ bĕ̇⁠mişĕ̌ţé֣̇h ha⁠yȧ֔yin mah-şĕ̇̌ʼéláţé֛⁠kĕ ʼesĕţé֥̇r ha⁠mȧlĕká֖̇h wĕ⁠ţiná֣̇ţéֽn lá֑⁠kĕ ẇ⁠mah-bȧqá̇şá̌ţé֛⁠kĕ ʻad-ẖàẕi֥y ha⁠mȧlĕk֖ẇţ wĕ⁠ţéʻáֽş̂׃"],[7,3,"וַ⁠תַּ֨עַן אֶסְתֵּ֤ר הַ⁠מַּלְכָּה֙ וַ⁠תֹּאמַ֔ר אִם־מָצָ֨אתִי חֵ֤ן בְּ⁠עֵינֶ֨י⁠ךָ֙ הַ⁠מֶּ֔לֶךְ וְ⁠אִם־עַל־הַ⁠מֶּ֖לֶךְ ט֑וֹב תִּנָּֽתֶן־לִ֤⁠י נַפְשִׁ⁠י֙ בִּ⁠שְׁאֵ֣לָתִ֔⁠י וְ⁠עַמִּ֖⁠י בְּ⁠בַקָּשָׁתִֽ⁠י׃","wa⁠ţȧ֨ʻan ʼesĕţé֤̇r ha⁠mȧlĕká̇h֙ wa⁠ţò̇ʼma֔r ʼim-máẕá֨ʼţiy ẖé֤n bĕ̇⁠ʻéyne֨y⁠ká֙ ha⁠mė֔lekĕ wĕ⁠ʼim-ʻal-ha⁠mė֖lekĕ t֑wòb ţi̇náֽ̇ţen-li֤⁠y napĕşǐ⁠y֙ bi̇⁠şĕ̌ʼé֣láţi֔⁠y wĕ⁠ʻami֖̇⁠y bĕ̇⁠baqá̇şá̌ţiֽ⁠y׃"],[7,4,"כִּ֤י נִמְכַּ֨רְנוּ֙ אֲנִ֣י וְ⁠עַמִּ֔⁠י לְ⁠הַשְׁמִ֖יד לַ⁠הֲר֣וֹג וּ⁠לְ⁠אַבֵּ֑ד וְ֠⁠אִלּוּ לַ⁠עֲבָדִ֨ים וְ⁠לִ⁠שְׁפָח֤וֹת נִמְכַּ֨רְנוּ֙ הֶחֱרַ֔שְׁתִּי כִּ֣י אֵ֥ין הַ⁠צָּ֛ר שֹׁוֶ֖ה בְּ⁠נֵ֥זֶק הַ⁠מֶּֽלֶךְ׃ס","ki֤̇y nimĕkȧ֨rĕnẇ֙ ʼàni֣y wĕ⁠ʻami̇֔⁠y lĕ⁠haşĕ̌mi֖yd la⁠hàr֣wòg ẇ⁠lĕ⁠ʼabé֑̇d wĕ֠⁠ʼil̇ẇ la⁠ʻàbádi֨ym wĕ⁠li⁠şĕ̌páẖ֤wòţ nimĕkȧ֨rĕnẇ֙ heẖèra֔şĕ̌ţi̇y ki֣̇y ʼé֥yn ha⁠ẕá֛̇r şò̌we֖h bĕ̇⁠né֥zeq ha⁠mėֽlekĕ׃s"],[7,5,"וַ⁠יֹּ֨אמֶר֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ וַ⁠יֹּ֖אמֶר לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֑ה מִ֣י ה֥וּא זֶה֙ וְ⁠אֵֽי־זֶ֣ה ה֔וּא אֲשֶׁר־מְלָא֥⁠וֹ לִבּ֖⁠וֹ לַ⁠עֲשׂ֥וֹת כֵּֽן׃","wa⁠yò̇֨ʼmer֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ wa⁠yò֖̇ʼmer lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká֑̇h mi֣y h֥ẇʼ zeh֙ wĕ⁠ʼéֽy-ze֣h h֔ẇʼ ʼàşěr-mĕláʼ֥⁠wò liḃ֖⁠wò la⁠ʻàş֥̂wòţ kéֽ̇n׃"],[7,6,"וַ⁠תֹּ֣אמֶר־אֶסְתֵּ֔ר אִ֚ישׁ צַ֣ר וְ⁠אוֹיֵ֔ב הָמָ֥ן הָ⁠רָ֖ע הַ⁠זֶּ֑ה וְ⁠הָמָ֣ן נִבְעַ֔ת מִ⁠לִּ⁠פְנֵ֥י הַ⁠מֶּ֖לֶךְ וְ⁠הַ⁠מַּלְכָּֽה׃","wa⁠ţò֣̇ʼmer-ʼesĕţé̇֔r ʼi֚yş̌ ẕa֣r wĕ⁠ʼwòyé֔b hámá֥n há⁠rá֖ʻ ha⁠zė֑h wĕ⁠hámá֣n nibĕʻa֔ţ mi⁠li̇⁠pĕné֥y ha⁠mė֖lekĕ wĕ⁠ha⁠mȧlĕkáֽ̇h׃"],[7,7,"וְ⁠הַ⁠מֶּ֜לֶךְ קָ֤ם בַּ⁠חֲמָת⁠וֹ֙ מִ⁠מִּשְׁתֵּ֣ה הַ⁠יַּ֔יִן אֶל־גִּנַּ֖ת הַ⁠בִּיתָ֑ן וְ⁠הָמָ֣ן עָמַ֗ד לְ⁠בַקֵּ֤שׁ עַל־נַפְשׁ⁠וֹ֙ מֵֽ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֔ה כִּ֣י רָאָ֔ה כִּֽי־כָלְתָ֥ה אֵלָ֛י⁠ו הָ⁠רָעָ֖ה מֵ⁠אֵ֥ת הַ⁠מֶּֽלֶךְ׃","wĕ⁠ha⁠mė֜lekĕ qá֤m bȧ⁠ẖàmáţ⁠wò֙ mi⁠mi̇şĕ̌ţé֣̇h ha⁠yȧ֔yin ʼel-gi̇nȧ֖ţ ha⁠bi̇yţá֑n wĕ⁠hámá֣n ʻáma֗d lĕ⁠baqé֤̇ş̌ ʻal-napĕş̌⁠wò֙ méֽ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֔h ki֣̇y ráʼá֔h kiֽ̇y-kálĕţá֥h ʼélá֛y⁠w há⁠ráʻá֖h mé⁠ʼé֥ţ ha⁠mėֽlekĕ׃"],[7,8,"וְ⁠הַ⁠מֶּ֡לֶךְ שָׁב֩ מִ⁠גִּנַּ֨ת הַ⁠בִּיתָ֜ן אֶל־בֵּ֣ית ׀ מִשְׁתֵּ֣ה הַ⁠יַּ֗יִן וְ⁠הָמָן֙ נֹפֵ֔ל עַל־הַ⁠מִּטָּה֙ אֲשֶׁ֣ר אֶסְתֵּ֣ר עָלֶ֔י⁠הָ וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ הֲ֠⁠גַם לִ⁠כְבּ֧וֹשׁ אֶת־הַ⁠מַּלְכָּ֛ה עִמִּ֖⁠י בַּ⁠בָּ֑יִת הַ⁠דָּבָ֗ר יָצָא֙ מִ⁠פִּ֣י הַ⁠מֶּ֔לֶךְ וּ⁠פְנֵ֥י הָמָ֖ן חָפֽוּ׃ס","wĕ⁠ha⁠mė֡lekĕ şá̌b֩ mi⁠gi̇nȧ֨ţ ha⁠bi̇yţá֜n ʼel-bé֣̇yţ ׀ mişĕ̌ţé֣̇h ha⁠yȧ֗yin wĕ⁠hámán֙ nòpé֔l ʻal-ha⁠mi̇tá̇h֙ ʼàşě֣r ʼesĕţé֣̇r ʻále֔y⁠há wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ hà֠⁠gam li⁠kĕḃ֧wòş̌ ʼeţ-ha⁠mȧlĕká֛̇h ʻimi֖̇⁠y bȧ⁠bá֑̇yiţ ha⁠dá̇bá֗r yáẕáʼ֙ mi⁠pi֣̇y ha⁠mė֔lekĕ ẇ⁠pĕné֥y hámá֖n ẖápֽẇ׃s"],[7,9,"וַ⁠יֹּ֣אמֶר חַ֠רְבוֹנָה אֶחָ֨ד מִן־הַ⁠סָּרִיסִ֜ים לִ⁠פְנֵ֣י הַ⁠מֶּ֗לֶךְ גַּ֣ם הִנֵּה־הָ⁠עֵ֣ץ אֲשֶׁר־עָשָׂ֪ה הָמָ֟ן לְֽ⁠מָרְדֳּכַ֞י אֲשֶׁ֧ר דִּבֶּר־ט֣וֹב עַל־הַ⁠מֶּ֗לֶךְ עֹמֵד֙ בְּ⁠בֵ֣ית הָמָ֔ן גָּבֹ֖הַּ חֲמִשִּׁ֣ים אַמָּ֑ה וַ⁠יֹּ֥אמֶר הַ⁠מֶּ֖לֶךְ תְּלֻ֥⁠הוּ עָלָֽי⁠ו׃","wa⁠yò֣̇ʼmer ẖa֠rĕbwònáh ʼeẖá֨d min-ha⁠sá̇riysi֜ym li⁠pĕné֣y ha⁠mė֗lekĕ gȧ֣m hiné̇h-há⁠ʻé֣ẕ ʼàşěr-ʻáşá֪̂h hámá֟n lĕֽ⁠márĕdȯka֞y ʼàşě֧r di̇bėr-t֣wòb ʻal-ha⁠mė֗lekĕ ʻòméd֙ bĕ̇⁠bé֣yţ hámá֔n gá̇bò֖hȧ ẖàmişi֣̇̌ym ʼamá֑̇h wa⁠yò֥̇ʼmer ha⁠mė֖lekĕ ţĕ̇lu֥⁠hẇ ʻáláֽy⁠w׃"],[7,10,"וַ⁠יִּתְלוּ֙ אֶת־הָמָ֔ן עַל־הָ⁠עֵ֖ץ אֲשֶׁר־הֵכִ֣ין לְ⁠מָרְדֳּכָ֑י וַ⁠חֲמַ֥ת הַ⁠מֶּ֖לֶךְ שָׁכָֽכָה׃פ","wa⁠yi̇ţĕlẇ֙ ʼeţ-hámá֔n ʻal-há⁠ʻé֖ẕ ʼàşěr-héki֣yn lĕ⁠márĕdȯká֑y wa⁠ẖàma֥ţ ha⁠mė֖lekĕ şá̌káֽkáh׃p"],[8,1,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא נָתַ֞ן הַ⁠מֶּ֤לֶךְ אֲחַשְׁוֵרוֹשׁ֙ לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֔ה אֶת־בֵּ֥ית הָמָ֖ן צֹרֵ֣ר היהודיים וּ⁠מָרְדֳּכַ֗י בָּ֚א לִ⁠פְנֵ֣י הַ⁠מֶּ֔לֶךְ כִּֽי־הִגִּ֥ידָה אֶסְתֵּ֖ר מַ֥ה הוּא־לָֽ⁠הּ׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ náţa֞n ha⁠mė֤lekĕ ʼàẖaşĕ̌wérwòş̌֙ lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֔h ʼeţ-bé֥̇yţ hámá֖n ẕòré֣r hyhwdyym ẇ⁠márĕdȯka֗y bá֚̇ʼ li⁠pĕné֣y ha⁠mė֔lekĕ kiֽ̇y-higi֥̇ydáh ʼesĕţé֖̇r ma֥h hẇʼ-láֽ⁠ḣ׃"],[8,2,"וַ⁠יָּ֨סַר הַ⁠מֶּ֜לֶךְ אֶת־טַבַּעְתּ֗⁠וֹ אֲשֶׁ֤ר הֶֽעֱבִיר֙ מֵֽ⁠הָמָ֔ן וַֽ⁠יִּתְּנָ֖⁠הּ לְ⁠מָרְדֳּכָ֑י וַ⁠תָּ֧שֶׂם אֶסְתֵּ֛ר אֶֽת־מָרְדֳּכַ֖י עַל־בֵּ֥ית הָמָֽן׃פ","wa⁠yá̇֨sar ha⁠mė֜lekĕ ʼeţ-tabȧʻĕţ̇֗⁠wò ʼàşě֤r heֽʻèbiyr֙ méֽ⁠hámá֔n waֽ⁠yi̇ţĕ̇ná֖⁠ḣ lĕ⁠márĕdȯká֑y wa⁠ţá֧̇şêm ʼesĕţé֛̇r ʼeֽţ-márĕdȯka֖y ʻal-bé֥̇yţ hámáֽn׃p"],[8,3,"וַ⁠תּ֣וֹסֶף אֶסְתֵּ֗ר וַ⁠תְּדַבֵּר֙ לִ⁠פְנֵ֣י הַ⁠מֶּ֔לֶךְ וַ⁠תִּפֹּ֖ל לִ⁠פְנֵ֣י רַגְלָ֑י⁠ו וַ⁠תֵּ֣בְךְּ וַ⁠תִּתְחַנֶּן־ל֗⁠וֹ לְ⁠הַֽעֲבִיר֙ אֶת־רָעַת֙ הָמָ֣ן הָֽ⁠אֲגָגִ֔י וְ⁠אֵת֙ מַֽחֲשַׁבְתּ֔⁠וֹ אֲשֶׁ֥ר חָשַׁ֖ב עַל־הַ⁠יְּהוּדִֽים׃","wa⁠ţ֣̇wòsep ʼesĕţé̇֗r wa⁠ţĕ̇dabé̇r֙ li⁠pĕné֣y ha⁠mė֔lekĕ wa⁠ţi̇pò֖̇l li⁠pĕné֣y ragĕlá֑y⁠w wa⁠ţé֣̇bĕkĕ̇ wa⁠ţi̇ţĕẖanėn-l֗⁠wò lĕ⁠haֽʻàbiyr֙ ʼeţ-ráʻaţ֙ hámá֣n háֽ⁠ʼàgági֔y wĕ⁠ʼéţ֙ maֽẖàşǎbĕţ̇֔⁠wò ʼàşě֥r ẖáşǎ֖b ʻal-ha⁠yĕ̇hẇdiֽym׃"],[8,4,"וַ⁠יּ֤וֹשֶׁט הַ⁠מֶּ֨לֶךְ֙ לְ⁠אֶסְתֵּ֔ר אֵ֖ת שַׁרְבִ֣ט הַ⁠זָּהָ֑ב וַ⁠תָּ֣קָם אֶסְתֵּ֔ר וַֽ⁠תַּעֲמֹ֖ד לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠ẏ֤wòşět ha⁠mė֨lekĕ֙ lĕ⁠ʼesĕţé̇֔r ʼé֖ţ şǎrĕbi֣t ha⁠zá̇há֑b wa⁠ţá֣̇qám ʼesĕţé̇֔r waֽ⁠ţȧʻàmò֖d li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[8,5,"וַ֠⁠תֹּאמֶר אִם־עַל־הַ⁠מֶּ֨לֶךְ ט֜וֹב וְ⁠אִם־מָצָ֧אתִי חֵ֣ן לְ⁠פָנָ֗י⁠ו וְ⁠כָשֵׁ֤ר הַ⁠דָּבָר֙ לִ⁠פְנֵ֣י הַ⁠מֶּ֔לֶךְ וְ⁠טוֹבָ֥ה אֲנִ֖י בְּ⁠עֵינָ֑י⁠ו יִכָּתֵ֞ב לְ⁠הָשִׁ֣יב אֶת־הַ⁠סְּפָרִ֗ים מַחֲשֶׁ֜בֶת הָמָ֤ן בֶּֽן־הַמְּדָ֨תָא֙ הָ⁠אֲגָגִ֔י אֲשֶׁ֣ר כָּתַ֗ב לְ⁠אַבֵּד֙ אֶת־הַ⁠יְּהוּדִ֔ים אֲשֶׁ֖ר בְּ⁠כָל־מְדִינ֥וֹת הַ⁠מֶּֽלֶךְ׃","wa֠⁠ţò̇ʼmer ʼim-ʻal-ha⁠mė֨lekĕ t֜wòb wĕ⁠ʼim-máẕá֧ʼţiy ẖé֣n lĕ⁠páná֗y⁠w wĕ⁠káşé֤̌r ha⁠dá̇bár֙ li⁠pĕné֣y ha⁠mė֔lekĕ wĕ⁠twòbá֥h ʼàni֖y bĕ̇⁠ʻéyná֑y⁠w yiká̇ţé֞b lĕ⁠háşǐ֣yb ʼeţ-ha⁠sĕ̇pári֗ym maẖàşě֜beţ hámá֤n bėֽn-hamĕ̇dá֨ţáʼ֙ há⁠ʼàgági֔y ʼàşě֣r ká̇ţa֗b lĕ⁠ʼabé̇d֙ ʼeţ-ha⁠yĕ̇hẇdi֔ym ʼàşě֖r bĕ̇⁠kál-mĕdiyn֥wòţ ha⁠mėֽlekĕ׃"],[8,6,"כִּ֠י אֵיכָכָ֤ה אוּכַל֙ וְֽ⁠רָאִ֔יתִי בָּ⁠רָעָ֖ה אֲשֶׁר־יִמְצָ֣א אֶת־עַמִּ֑⁠י וְ⁠אֵֽיכָכָ֤ה אוּכַל֙ וְֽ⁠רָאִ֔יתִי בְּ⁠אָבְדַ֖ן מוֹלַדְתִּֽ⁠י׃ס","ki̇֠y ʼéykáká֤h ʼẇkal֙ wĕֽ⁠ráʼi֔yţiy bá̇⁠ráʻá֖h ʼàşěr-yimĕẕá֣ʼ ʼeţ-ʻami֑̇⁠y wĕ⁠ʼéֽykáká֤h ʼẇkal֙ wĕֽ⁠ráʼi֔yţiy bĕ̇⁠ʼábĕda֖n mwòladĕţiֽ̇⁠y׃s"],[8,7,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֤לֶךְ אֲחַשְׁוֵרֹשׁ֙ לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֔ה וּֽ⁠לְ⁠מָרְדֳּכַ֖י הַ⁠יְּהוּדִ֑י הִנֵּ֨ה בֵית־הָמָ֜ן נָתַ֣תִּי לְ⁠אֶסְתֵּ֗ר וְ⁠אֹת⁠וֹ֙ תָּל֣וּ עַל־הָ⁠עֵ֔ץ עַ֛ל אֲשֶׁר־שָׁלַ֥ח יָד֖⁠וֹ ביהודיים׃","wa⁠yò̇֨ʼmer ha⁠mė֤lekĕ ʼàẖaşĕ̌wéròş̌֙ lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֔h ẇֽ⁠lĕ⁠márĕdȯka֖y ha⁠yĕ̇hẇdi֑y hiné̇֨h béyţ-hámá֜n náţa֣ţi̇y lĕ⁠ʼesĕţé̇֗r wĕ⁠ʼòţ⁠wò֙ ţá̇l֣ẇ ʻal-há⁠ʻé֔ẕ ʻa֛l ʼàşěr-şá̌la֥ẖ yád֖⁠wò byhwdyym׃"],[8,8,"וְ֠⁠אַתֶּם כִּתְב֨וּ עַל־הַ⁠יְּהוּדִ֜ים כַּ⁠טּ֤וֹב בְּ⁠עֵֽינֵי⁠כֶם֙ בְּ⁠שֵׁ֣ם הַ⁠מֶּ֔לֶךְ וְ⁠חִתְמ֖וּ בְּ⁠טַבַּ֣עַת הַ⁠מֶּ֑לֶךְ כִּֽי־כְתָ֞ב אֲשֶׁר־נִכְתָּ֣ב בְּ⁠שֵׁם־הַ⁠מֶּ֗לֶךְ וְ⁠נַחְתּ֛וֹם בְּ⁠טַבַּ֥עַת הַ⁠מֶּ֖לֶךְ אֵ֥ין לְ⁠הָשִֽׁיב׃","wĕ֠⁠ʼaţėm ki̇ţĕb֨ẇ ʻal-ha⁠yĕ̇hẇdi֜ym kȧ⁠ṫ֤wòb bĕ̇⁠ʻéֽynéy⁠kem֙ bĕ̇⁠şé֣̌m ha⁠mė֔lekĕ wĕ⁠ẖiţĕm֖ẇ bĕ̇⁠tabȧ֣ʻaţ ha⁠mė֑lekĕ kiֽ̇y-kĕţá֞b ʼàşěr-nikĕţá֣̇b bĕ̇⁠şé̌m-ha⁠mė֗lekĕ wĕ⁠naẖĕţ֛̇wòm bĕ̇⁠tabȧ֥ʻaţ ha⁠mė֖lekĕ ʼé֥yn lĕ⁠háşǐֽyb׃"],[8,9,"וַ⁠יִּקָּרְא֣וּ סֹפְרֵֽי־הַ⁠מֶּ֣לֶךְ בָּֽ⁠עֵת־הַ֠⁠הִיא בַּ⁠חֹ֨דֶשׁ הַ⁠שְּׁלִישִׁ֜י הוּא־חֹ֣דֶשׁ סִיוָ֗ן בִּ⁠שְׁלוֹשָׁ֣ה וְ⁠עֶשְׂרִים֮ בּ⁠וֹ֒ וַ⁠יִּכָּתֵ֣ב כְּֽ⁠כָל־אֲשֶׁר־צִוָּ֣ה מָרְדֳּכַ֣י אֶל־הַ⁠יְּהוּדִ֡ים וְ⁠אֶ֣ל הָ⁠אֲחַשְׁדַּרְפְּנִֽים־וְ⁠הַ⁠פַּחוֹת֩ וְ⁠שָׂרֵ֨י הַ⁠מְּדִינ֜וֹת אֲשֶׁ֣ר ׀ מֵ⁠הֹ֣דּוּ וְ⁠עַד־כּ֗וּשׁ שֶׁ֣בַע וְ⁠עֶשְׂרִ֤ים וּ⁠מֵאָה֙ מְדִינָ֔ה מְדִינָ֤ה וּ⁠מְדִינָה֙ כִּ⁠כְתָבָ֔⁠הּ וְ⁠עַ֥ם וָ⁠עָ֖ם כִּ⁠לְשֹׁנ֑⁠וֹ וְ⁠אֶ֨ל־הַ⁠יְּהוּדִ֔ים כִּ⁠כְתָבָ֖⁠ם וְ⁠כִ⁠לְשׁוֹנָֽ⁠ם׃","wa⁠yi̇qá̇rĕʼ֣ẇ sòpĕréֽy-ha⁠mė֣lekĕ báֽ̇⁠ʻéţ-ha֠⁠hiyʼ bȧ⁠ẖò֨deş̌ ha⁠şĕ̇̌liyşǐ֜y hẇʼ-ẖò֣deş̌ siywá֗n bi̇⁠şĕ̌lwòşá֣̌h wĕ⁠ʻeşĕ̂riym֮ ḃ⁠wò֒ wa⁠yi̇ká̇ţé֣b kĕֽ̇⁠kál-ʼàşěr-ẕiwá֣̇h márĕdȯka֣y ʼel-ha⁠yĕ̇hẇdi֡ym wĕ⁠ʼe֣l há⁠ʼàẖaşĕ̌dȧrĕpĕ̇niֽym-wĕ⁠ha⁠pȧẖwòţ֩ wĕ⁠şá̂ré֨y ha⁠mĕ̇diyn֜wòţ ʼàşě֣r ׀ mé⁠hò֣ḋẇ wĕ⁠ʻad-k̇֗ẇş̌ şě֣baʻ wĕ⁠ʻeşĕ̂ri֤ym ẇ⁠méʼáh֙ mĕdiyná֔h mĕdiyná֤h ẇ⁠mĕdiynáh֙ ki̇⁠kĕţábá֔⁠ḣ wĕ⁠ʻa֥m wá⁠ʻá֖m ki̇⁠lĕşò̌n֑⁠wò wĕ⁠ʼe֨l-ha⁠yĕ̇hẇdi֔ym ki̇⁠kĕţábá֖⁠m wĕ⁠ki⁠lĕş̌wònáֽ⁠m׃"],[8,10,"וַ⁠יִּכְתֹּ֗ב בְּ⁠שֵׁם֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵרֹ֔שׁ וַ⁠יַּחְתֹּ֖ם בְּ⁠טַבַּ֣עַת הַ⁠מֶּ֑לֶךְ וַ⁠יִּשְׁלַ֣ח סְפָרִ֡ים בְּ⁠יַד֩ הָ⁠רָצִ֨ים בַּ⁠סּוּסִ֜ים רֹכְבֵ֤י הָ⁠רֶ֨כֶשׁ֙ הָֽ⁠אֲחַשְׁתְּרָנִ֔ים בְּנֵ֖י הָֽ⁠רַמָּכִֽים׃","wa⁠yi̇kĕţò̇֗b bĕ̇⁠şé̌m֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wérò֔ş̌ wa⁠yȧẖĕţò֖̇m bĕ̇⁠tabȧ֣ʻaţ ha⁠mė֑lekĕ wa⁠yi̇şĕ̌la֣ẖ sĕpári֡ym bĕ̇⁠yad֩ há⁠ráẕi֨ym bȧ⁠ṡẇsi֜ym ròkĕbé֤y há⁠re֨keş̌֙ háֽ⁠ʼàẖaşĕ̌ţĕ̇ráni֔ym bĕ̇né֖y háֽ⁠ramá̇kiֽym׃"],[8,11,"אֲשֶׁר֩ נָתַ֨ן הַ⁠מֶּ֜לֶךְ לַ⁠יְּהוּדִ֣ים ׀ אֲשֶׁ֣ר בְּ⁠כָל־עִיר־וָ⁠עִ֗יר לְ⁠הִקָּהֵל֮ וְ⁠לַ⁠עֲמֹ֣ד עַל־נַפְשָׁ⁠ם֒ לְ⁠הַשְׁמִיד֩ וְ⁠לַ⁠הֲרֹ֨ג וּ⁠לְ⁠אַבֵּ֜ד אֶת־כָּל־חֵ֨יל עַ֧ם וּ⁠מְדִינָ֛ה הַ⁠צָּרִ֥ים אֹתָ֖⁠ם טַ֣ף וְ⁠נָשִׁ֑ים וּ⁠שְׁלָלָ֖⁠ם לָ⁠בֽוֹז׃","ʼàşěr֩ náţa֨n ha⁠mė֜lekĕ la⁠yĕ̇hẇdi֣ym ׀ ʼàşě֣r bĕ̇⁠kál-ʻiyr-wá⁠ʻi֗yr lĕ⁠hiqá̇hél֮ wĕ⁠la⁠ʻàmò֣d ʻal-napĕşá̌⁠m֒ lĕ⁠haşĕ̌miyd֩ wĕ⁠la⁠hàrò֨g ẇ⁠lĕ⁠ʼabé̇֜d ʼeţ-ká̇l-ẖé֨yl ʻa֧m ẇ⁠mĕdiyná֛h ha⁠ẕá̇ri֥ym ʼòţá֖⁠m ta֣p wĕ⁠náşǐ֑ym ẇ⁠şĕ̌lálá֖⁠m lá⁠bֽwòz׃"],[8,12,"בְּ⁠י֣וֹם אֶחָ֔ד בְּ⁠כָל־מְדִינ֖וֹת הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֑וֹשׁ בִּ⁠שְׁלוֹשָׁ֥ה עָשָׂ֛ר לְ⁠חֹ֥דֶשׁ שְׁנֵים־עָשָׂ֖ר הוּא־חֹ֥דֶשׁ אֲדָֽר׃","bĕ̇⁠y֣wòm ʼeẖá֔d bĕ̇⁠kál-mĕdiyn֖wòţ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֑wòş̌ bi̇⁠şĕ̌lwòşá֥̌h ʻáşá֛̂r lĕ⁠ẖò֥deş̌ şĕ̌néym-ʻáşá֖̂r hẇʼ-ẖò֥deş̌ ʼàdáֽr׃"],[8,13,"פַּתְשֶׁ֣גֶן הַ⁠כְּתָ֗ב לְ⁠הִנָּ֤תֵֽן דָּת֙ בְּ⁠כָל־מְדִינָ֣ה וּ⁠מְדִינָ֔ה גָּל֖וּי לְ⁠כָל־הָ⁠עַמִּ֑ים וְ⁠לִ⁠הְי֨וֹת היהודיים עתודים לַ⁠יּ֣וֹם הַ⁠זֶּ֔ה לְ⁠הִנָּקֵ֖ם מֵ⁠אֹיְבֵי⁠הֶֽם׃","pȧţĕşě֣gen ha⁠kĕ̇ţá֗b lĕ⁠hiná֤̇ţéֽn dá̇ţ֙ bĕ̇⁠kál-mĕdiyná֣h ẇ⁠mĕdiyná֔h gá̇l֖ẇy lĕ⁠kál-há⁠ʻami֑̇ym wĕ⁠li⁠hĕy֨wòţ hyhwdyym ʻţwdym la⁠ẏ֣wòm ha⁠zė֔h lĕ⁠hiná̇qé֖m mé⁠ʼòyĕbéy⁠heֽm׃"],[8,14,"הָ⁠רָצִ֞ים רֹכְבֵ֤י הָ⁠רֶ֨כֶשׁ֙ הָֽ⁠אֲחַשְׁתְּרָנִ֔ים יָֽצְא֛וּ מְבֹהָלִ֥ים וּ⁠דְחוּפִ֖ים בִּ⁠דְבַ֣ר הַ⁠מֶּ֑לֶךְ וְ⁠הַ⁠דָּ֥ת נִתְּנָ֖ה בְּ⁠שׁוּשַׁ֥ן הַ⁠בִּירָֽה׃פ","há⁠ráẕi֞ym ròkĕbé֤y há⁠re֨keş̌֙ háֽ⁠ʼàẖaşĕ̌ţĕ̇ráni֔ym yáֽẕĕʼ֛ẇ mĕbòháli֥ym ẇ⁠dĕẖẇpi֖ym bi̇⁠dĕba֣r ha⁠mė֑lekĕ wĕ⁠ha⁠dá֥̇ţ niţĕ̇ná֖h bĕ̇⁠ş̌ẇşǎ֥n ha⁠bi̇yráֽh׃p"],[8,15,"וּ⁠מָרְדֳּכַ֞י יָצָ֣א ׀ מִ⁠לִּ⁠פְנֵ֣י הַ⁠מֶּ֗לֶךְ בִּ⁠לְב֤וּשׁ מַלְכוּת֙ תְּכֵ֣לֶת וָ⁠ח֔וּר וַ⁠עֲטֶ֤רֶת זָהָב֙ גְּדוֹלָ֔ה וְ⁠תַכְרִ֥יךְ בּ֖וּץ וְ⁠אַרְגָּמָ֑ן וְ⁠הָ⁠עִ֣יר שׁוּשָׁ֔ן צָהֲלָ֖ה וְ⁠שָׂמֵֽחָה׃","ẇ⁠márĕdȯka֞y yáẕá֣ʼ ׀ mi⁠li̇⁠pĕné֣y ha⁠mė֗lekĕ bi̇⁠lĕb֤ẇş̌ malĕkẇţ֙ ţĕ̇ké֣leţ wá⁠ẖ֔ẇr wa⁠ʻàte֤reţ záháb֙ gĕ̇dwòlá֔h wĕ⁠ţakĕri֥ykĕ ḃ֖ẇẕ wĕ⁠ʼarĕgá̇má֑n wĕ⁠há⁠ʻi֣yr ş̌ẇşá̌֔n ẕáhàlá֖h wĕ⁠şá̂méֽẖáh׃"],[8,16,"לַ⁠יְּהוּדִ֕ים הָֽיְתָ֥ה אוֹרָ֖ה וְ⁠שִׂמְחָ֑ה וְ⁠שָׂשֹׂ֖ן וִ⁠יקָֽר׃","la⁠yĕ̇hẇdi֕ym háֽyĕţá֥h ʼwòrá֖h wĕ⁠şîmĕẖá֑h wĕ⁠şá̂şò֖̂n wi⁠yqáֽr׃"],[8,17,"וּ⁠בְ⁠כָל־מְדִינָ֨ה וּ⁠מְדִינָ֜ה וּ⁠בְ⁠כָל־עִ֣יר וָ⁠עִ֗יר מְקוֹם֙ אֲשֶׁ֨ר דְּבַר־הַ⁠מֶּ֤לֶךְ וְ⁠דָת⁠וֹ֙ מַגִּ֔יעַ שִׂמְחָ֤ה וְ⁠שָׂשׂוֹן֙ לַ⁠יְּהוּדִ֔ים מִשְׁתֶּ֖ה וְ⁠י֣וֹם ט֑וֹב וְ⁠רַבִּ֞ים מֵֽ⁠עַמֵּ֤י הָ⁠אָ֨רֶץ֙ מִֽתְיַהֲדִ֔ים כִּֽי־נָפַ֥ל פַּֽחַד־הַ⁠יְּהוּדִ֖ים עֲלֵי⁠הֶֽם׃","ẇ⁠bĕ⁠kál-mĕdiyná֨h ẇ⁠mĕdiyná֜h ẇ⁠bĕ⁠kál-ʻi֣yr wá⁠ʻi֗yr mĕqwòm֙ ʼàşě֨r dĕ̇bar-ha⁠mė֤lekĕ wĕ⁠dáţ⁠wò֙ magi̇֔yʻa şîmĕẖá֤h wĕ⁠şá̂ş̂wòn֙ la⁠yĕ̇hẇdi֔ym mişĕ̌ţė֖h wĕ⁠y֣wòm t֑wòb wĕ⁠rabi̇֞ym méֽ⁠ʻamé֤̇y há⁠ʼá֨reẕ֙ miֽţĕyahàdi֔ym kiֽ̇y-nápa֥l pȧֽẖad-ha⁠yĕ̇hẇdi֖ym ʻàléy⁠heֽm׃"],[9,1,"וּ⁠בִ⁠שְׁנֵים֩ עָשָׂ֨ר חֹ֜דֶשׁ הוּא־חֹ֣דֶשׁ אֲדָ֗ר בִּ⁠שְׁלוֹשָׁ֨ה עָשָׂ֥ר יוֹם֙ בּ֔⁠וֹ אֲשֶׁ֨ר הִגִּ֧יעַ דְּבַר־הַ⁠מֶּ֛לֶךְ וְ⁠דָת֖⁠וֹ לְ⁠הֵעָשׂ֑וֹת בַּ⁠יּ֗וֹם אֲשֶׁ֨ר שִׂבְּר֜וּ אֹיְבֵ֤י הַ⁠יְּהוּדִים֙ לִ⁠שְׁל֣וֹט בָּ⁠הֶ֔ם וְ⁠נַהֲפ֣וֹךְ ה֔וּא אֲשֶׁ֨ר יִשְׁלְט֧וּ הַ⁠יְּהוּדִ֛ים הֵ֖מָּה בְּ⁠שֹׂנְאֵי⁠הֶֽם׃","ẇ⁠bi⁠şĕ̌néym֩ ʻáşá̂֨r ẖò֜deş̌ hẇʼ-ẖò֣deş̌ ʼàdá֗r bi̇⁠şĕ̌lwòşá̌֨h ʻáşá֥̂r ywòm֙ ḃ֔⁠wò ʼàşě֨r higi֧̇yʻa dĕ̇bar-ha⁠mė֛lekĕ wĕ⁠dáţ֖⁠wò lĕ⁠héʻáş֑̂wòţ bȧ⁠ẏ֗wòm ʼàşě֨r şîbĕ̇r֜ẇ ʼòyĕbé֤y ha⁠yĕ̇hẇdiym֙ li⁠şĕ̌l֣wòt bá̇⁠he֔m wĕ⁠nahàp֣wòkĕ h֔ẇʼ ʼàşě֨r yişĕ̌lĕt֧ẇ ha⁠yĕ̇hẇdi֛ym hé֖má̇h bĕ̇⁠şò̂nĕʼéy⁠heֽm׃"],[9,2,"נִקְהֲל֨וּ הַ⁠יְּהוּדִ֜ים בְּ⁠עָרֵי⁠הֶ֗ם בְּ⁠כָל־מְדִינוֹת֙ הַ⁠מֶּ֣לֶךְ אֳחַשְׁוֵר֔וֹשׁ לִ⁠שְׁלֹ֣חַ יָ֔ד בִּ⁠מְבַקְשֵׁ֖י רָֽעָתָ֑⁠ם וְ⁠אִישׁ֙ לֹא־עָמַ֣ד לִ⁠פְנֵי⁠הֶ֔ם כִּֽי־נָפַ֥ל פַּחְדָּ֖⁠ם עַל־כָּל־הָ⁠עַמִּֽים׃","niqĕhàl֨ẇ ha⁠yĕ̇hẇdi֜ym bĕ̇⁠ʻáréy⁠he֗m bĕ̇⁠kál-mĕdiynwòţ֙ ha⁠mė֣lekĕ ʼoẖaşĕ̌wér֔wòş̌ li⁠şĕ̌lò֣ẖa yá֔d bi̇⁠mĕbaqĕşé֖̌y ráֽʻáţá֑⁠m wĕ⁠ʼiyş̌֙ lòʼ-ʻáma֣d li⁠pĕnéy⁠he֔m kiֽ̇y-nápa֥l pȧẖĕdá֖̇⁠m ʻal-ká̇l-há⁠ʻamiֽ̇ym׃"],[9,3,"וְ⁠כָל־שָׂרֵ֨י הַ⁠מְּדִינ֜וֹת וְ⁠הָ⁠אֲחַשְׁדַּרְפְּנִ֣ים וְ⁠הַ⁠פַּח֗וֹת וְ⁠עֹשֵׂ֤י הַ⁠מְּלָאכָה֙ אֲשֶׁ֣ר לַ⁠מֶּ֔לֶךְ מְנַשְּׂאִ֖ים אֶת־הַ⁠יְּהוּדִ֑ים כִּֽי־נָפַ֥ל פַּֽחַד־מָרְדֳּכַ֖י עֲלֵי⁠הֶֽם׃","wĕ⁠kál-şá̂ré֨y ha⁠mĕ̇diyn֜wòţ wĕ⁠há⁠ʼàẖaşĕ̌dȧrĕpĕ̇ni֣ym wĕ⁠ha⁠pȧẖ֗wòţ wĕ⁠ʻòşé֤̂y ha⁠mĕ̇láʼkáh֙ ʼàşě֣r la⁠mė֔lekĕ mĕnaşĕ̇̂ʼi֖ym ʼeţ-ha⁠yĕ̇hẇdi֑ym kiֽ̇y-nápa֥l pȧֽẖad-márĕdȯka֖y ʻàléy⁠heֽm׃"],[9,4,"כִּֽי־גָ֤דוֹל מָרְדֳּכַי֙ בְּ⁠בֵ֣ית הַ⁠מֶּ֔לֶךְ וְ⁠שָׁמְע֖⁠וֹ הוֹלֵ֣ךְ בְּ⁠כָל־הַ⁠מְּדִינ֑וֹת כִּֽי־הָ⁠אִ֥ישׁ מָרְדֳּכַ֖י הוֹלֵ֥ךְ וְ⁠גָדֽוֹל׃פ","kiֽ̇y-gá֤dwòl márĕdȯkay֙ bĕ̇⁠bé֣yţ ha⁠mė֔lekĕ wĕ⁠şá̌mĕʻ֖⁠wò hwòlé֣kĕ bĕ̇⁠kál-ha⁠mĕ̇diyn֑wòţ kiֽ̇y-há⁠ʼi֥yş̌ márĕdȯka֖y hwòlé֥kĕ wĕ⁠gádֽwòl׃p"],[9,5,"וַ⁠יַּכּ֤וּ הַ⁠יְּהוּדִים֙ בְּ⁠כָל־אֹ֣יְבֵי⁠הֶ֔ם מַכַּת־חֶ֥רֶב וְ⁠הֶ֖רֶג וְ⁠אַבְדָ֑ן וַ⁠יַּֽעֲשׂ֥וּ בְ⁠שֹׂנְאֵי⁠הֶ֖ם כִּ⁠רְצוֹנָֽ⁠ם׃","wa⁠yȧk֤̇ẇ ha⁠yĕ̇hẇdiym֙ bĕ̇⁠kál-ʼò֣yĕbéy⁠he֔m makȧţ-ẖe֥reb wĕ⁠he֖reg wĕ⁠ʼabĕdá֑n wa⁠yȧֽʻàş֥̂ẇ bĕ⁠şò̂nĕʼéy⁠he֖m ki̇⁠rĕẕwònáֽ⁠m׃"],[9,6,"וּ⁠בְ⁠שׁוּשַׁ֣ן הַ⁠בִּירָ֗ה הָרְג֤וּ הַ⁠יְּהוּדִים֙ וְ⁠אַבֵּ֔ד חֲמֵ֥שׁ מֵא֖וֹת אִֽישׁ׃","ẇ⁠bĕ⁠ş̌ẇşǎ֣n ha⁠bi̇yrá֗h hárĕg֤ẇ ha⁠yĕ̇hẇdiym֙ wĕ⁠ʼabé̇֔d ẖàmé֥ş̌ méʼ֖wòţ ʼiֽyş̌׃"],[9,7,"וְ⁠אֵ֧ת ׀ פַּרְשַׁנְדָּ֛תָא וְ⁠אֵ֥ת ׀ דַּֽלְפ֖וֹן וְ⁠אֵ֥ת ׀ אַסְפָּֽתָא׃","wĕ⁠ʼé֧ţ ׀ pȧrĕşǎnĕdá֛̇ţáʼ wĕ⁠ʼé֥ţ ׀ dȧֽlĕp֖wòn wĕ⁠ʼé֥ţ ׀ ʼasĕpáֽ̇ţáʼ׃"],[9,8,"וְ⁠אֵ֧ת ׀ פּוֹרָ֛תָא וְ⁠אֵ֥ת ׀ אֲדַלְיָ֖א וְ⁠אֵ֥ת ׀ אֲרִידָֽתָא׃","wĕ⁠ʼé֧ţ ׀ ṗwòrá֛ţáʼ wĕ⁠ʼé֥ţ ׀ ʼàdalĕyá֖ʼ wĕ⁠ʼé֥ţ ׀ ʼàriydáֽţáʼ׃"],[9,9,"וְ⁠אֵ֤ת ׀ פַּרְמַ֨שְׁתָּא֙ וְ⁠אֵ֣ת ׀ אֲרִיסַ֔י וְ⁠אֵ֥ת ׀ אֲרִדַ֖י וְ⁠אֵ֥ת ׀ וַיְזָֽתָא׃","wĕ⁠ʼé֤ţ ׀ pȧrĕma֨şĕ̌ţá̇ʼ֙ wĕ⁠ʼé֣ţ ׀ ʼàriysa֔y wĕ⁠ʼé֥ţ ׀ ʼàrida֖y wĕ⁠ʼé֥ţ ׀ wayĕzáֽţáʼ׃"],[9,10,"עֲ֠שֶׂרֶת בְּנֵ֨י הָמָ֧ן בֶּֽן־הַמְּדָ֛תָא צֹרֵ֥ר הַ⁠יְּהוּדִ֖ים הָרָ֑גוּ וּ⁠בַ֨⁠בִּזָּ֔ה לֹ֥א שָׁלְח֖וּ אֶת־יָדָֽ⁠ם׃","ʻà֠şêreţ bĕ̇né֨y hámá֧n bėֽn-hamĕ̇dá֛ţáʼ ẕòré֥r ha⁠yĕ̇hẇdi֖ym hárá֑gẇ ẇ⁠ba֨⁠bi̇zá̇֔h lò֥ʼ şá̌lĕẖ֖ẇ ʼeţ-yádáֽ⁠m׃"],[9,11,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא בָּ֣א מִסְפַּ֧ר הַֽ⁠הֲרוּגִ֛ים בְּ⁠שׁוּשַׁ֥ן הַ⁠בִּירָ֖ה לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃ס","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ bá֣̇ʼ misĕpȧ֧r hֽa⁠hàrẇgi֛ym bĕ̇⁠ş̌ẇşǎ֥n ha⁠bi̇yrá֖h li⁠pĕné֥y ha⁠mėֽlekĕ׃s"],[9,12,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֗ה בְּ⁠שׁוּשַׁ֣ן הַ⁠בִּירָ֡ה הָרְגוּ֩ הַ⁠יְּהוּדִ֨ים וְ⁠אַבֵּ֜ד חֲמֵ֧שׁ מֵא֣וֹת אִ֗ישׁ וְ⁠אֵת֙ עֲשֶׂ֣רֶת בְּנֵֽי־הָמָ֔ן בִּ⁠שְׁאָ֛ר מְדִינ֥וֹת הַ⁠מֶּ֖לֶךְ מֶ֣ה עָשׂ֑וּ וּ⁠מַה־שְּׁאֵֽלָתֵ⁠ךְ֙ וְ⁠יִנָּ֣תֵֽן לָ֔⁠ךְ וּ⁠מַה־בַּקָּשָׁתֵ֥⁠ךְ ע֖וֹד וְ⁠תֵעָֽשׂ׃","wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֗h bĕ̇⁠ş̌ẇşǎ֣n ha⁠bi̇yrá֡h hárĕgẇ֩ ha⁠yĕ̇hẇdi֨ym wĕ⁠ʼabé̇֜d ẖàmé֧ş̌ méʼ֣wòţ ʼi֗yş̌ wĕ⁠ʼéţ֙ ʻàşê֣reţ bĕ̇néֽy-hámá֔n bi̇⁠şĕ̌ʼá֛r mĕdiyn֥wòţ ha⁠mė֖lekĕ me֣h ʻáş֑̂ẇ ẇ⁠mah-şĕ̇̌ʼéֽláţé⁠kĕ֙ wĕ⁠yiná֣̇ţéֽn lá֔⁠kĕ ẇ⁠mah-bȧqá̇şá̌ţé֥⁠kĕ ʻ֖wòd wĕ⁠ţéʻáֽş̂׃"],[9,13,"וַ⁠תֹּ֤אמֶר אֶסְתֵּר֙ אִם־עַל־הַ⁠מֶּ֣לֶךְ ט֔וֹב יִנָּתֵ֣ן גַּם־מָחָ֗ר לַ⁠יְּהוּדִים֙ אֲשֶׁ֣ר בְּ⁠שׁוּשָׁ֔ן לַ⁠עֲשׂ֖וֹת כְּ⁠דָ֣ת הַ⁠יּ֑וֹם וְ⁠אֵ֛ת עֲשֶׂ֥רֶת בְּנֵֽי־הָמָ֖ן יִתְל֥וּ עַל־הָ⁠עֵֽץ׃","wa⁠ţò֤̇ʼmer ʼesĕţé̇r֙ ʼim-ʻal-ha⁠mė֣lekĕ t֔wòb yiná̇ţé֣n gȧm-máẖá֗r la⁠yĕ̇hẇdiym֙ ʼàşě֣r bĕ̇⁠ş̌ẇşá̌֔n la⁠ʻàş֖̂wòţ kĕ̇⁠dá֣ţ ha⁠ẏ֑wòm wĕ⁠ʼé֛ţ ʻàşê֥reţ bĕ̇néֽy-hámá֖n yiţĕl֥ẇ ʻal-há⁠ʻéֽẕ׃"],[9,14,"וַ⁠יֹּ֤אמֶר הַ⁠מֶּ֨לֶךְ֙ לְ⁠הֵֽעָשׂ֣וֹת כֵּ֔ן וַ⁠תִּנָּתֵ֥ן דָּ֖ת בְּ⁠שׁוּשָׁ֑ן וְ⁠אֵ֛ת עֲשֶׂ֥רֶת בְּנֵֽי־הָמָ֖ן תָּלֽוּ׃","wa⁠yò֤̇ʼmer ha⁠mė֨lekĕ֙ lĕ⁠héֽʻáş֣̂wòţ ké̇֔n wa⁠ţi̇ná̇ţé֥n dá֖̇ţ bĕ̇⁠ş̌ẇşá֑̌n wĕ⁠ʼé֛ţ ʻàşê֥reţ bĕ̇néֽy-hámá֖n ţá̇lֽẇ׃"],[9,15,"וַ⁠יִּֽקָּהֲל֞וּ היהודיים אֲשֶׁר־בְּ⁠שׁוּשָׁ֗ן גַּ֠ם בְּ⁠י֣וֹם אַרְבָּעָ֤ה עָשָׂר֙ לְ⁠חֹ֣דֶשׁ אֲדָ֔ר וַ⁠יַּֽהַרְג֣וּ בְ⁠שׁוּשָׁ֔ן שְׁלֹ֥שׁ מֵא֖וֹת אִ֑ישׁ וּ⁠בַ֨⁠בִּזָּ֔ה לֹ֥א שָׁלְח֖וּ אֶת־יָדָֽ⁠ם׃","wa⁠yiֽ̇qá̇hàl֞ẇ hyhwdyym ʼàşěr-bĕ̇⁠ş̌ẇşá̌֗n gȧ֠m bĕ̇⁠y֣wòm ʼarĕbá̇ʻá֤h ʻáşá̂r֙ lĕ⁠ẖò֣deş̌ ʼàdá֔r wa⁠ẏֽaharĕg֣ẇ bĕ⁠ş̌ẇşá̌֔n şĕ̌lò֥ş̌ méʼ֖wòţ ʼi֑yş̌ ẇ⁠ba֨⁠bi̇zá̇֔h lò֥ʼ şá̌lĕẖ֖ẇ ʼeţ-yádáֽ⁠m׃"],[9,16,"וּ⁠שְׁאָ֣ר הַ⁠יְּהוּדִ֡ים אֲשֶׁר֩ בִּ⁠מְדִינ֨וֹת הַ⁠מֶּ֜לֶךְ נִקְהֲל֣וּ ׀ וְ⁠עָמֹ֣ד עַל־נַפְשָׁ֗⁠ם וְ⁠נ֨וֹחַ֙ מֵ⁠אֹ֣יְבֵי⁠הֶ֔ם וְ⁠הָרֹג֙ בְּ⁠שֹׂ֣נְאֵי⁠הֶ֔ם חֲמִשָּׁ֥ה וְ⁠שִׁבְעִ֖ים אָ֑לֶף וּ⁠בַ֨⁠בִּזָּ֔ה לֹ֥א שָֽׁלְח֖וּ אֶת־יָדָֽ⁠ם׃","ẇ⁠şĕ̌ʼá֣r ha⁠yĕ̇hẇdi֡ym ʼàşěr֩ bi̇⁠mĕdiyn֨wòţ ha⁠mė֜lekĕ niqĕhàl֣ẇ ׀ wĕ⁠ʻámò֣d ʻal-napĕşá̌֗⁠m wĕ⁠n֨wòẖa֙ mé⁠ʼò֣yĕbéy⁠he֔m wĕ⁠háròg֙ bĕ̇⁠şò֣̂nĕʼéy⁠he֔m ẖàmişá֥̇̌h wĕ⁠şǐbĕʻi֖ym ʼá֑lep ẇ⁠ba֨⁠bi̇zá̇֔h lò֥ʼ şáֽ̌lĕẖ֖ẇ ʼeţ-yádáֽ⁠m׃"],[9,17,"בְּ⁠יוֹם־שְׁלֹשָׁ֥ה עָשָׂ֖ר לְ⁠חֹ֣דֶשׁ אֲדָ֑ר וְ⁠נ֗וֹחַ בְּ⁠אַרְבָּעָ֤ה עָשָׂר֙ בּ֔⁠וֹ וְ⁠עָשֹׂ֣ה אֹת֔⁠וֹ י֖וֹם מִשְׁתֶּ֥ה וְ⁠שִׂמְחָֽה׃","bĕ̇⁠ywòm-şĕ̌lòşá֥̌h ʻáşá֖̂r lĕ⁠ẖò֣deş̌ ʼàdá֑r wĕ⁠n֗wòẖa bĕ̇⁠ʼarĕbá̇ʻá֤h ʻáşá̂r֙ ḃ֔⁠wò wĕ⁠ʻáşò֣̂h ʼòţ֔⁠wò y֖wòm mişĕ̌ţė֥h wĕ⁠şîmĕẖáֽh׃"],[9,18,"והיהודיים אֲשֶׁר־בְּ⁠שׁוּשָׁ֗ן נִקְהֲלוּ֙ בִּ⁠שְׁלֹשָׁ֤ה עָשָׂר֙ בּ֔⁠וֹ וּ⁠בְ⁠אַרְבָּעָ֥ה עָשָׂ֖ר בּ֑⁠וֹ וְ⁠נ֗וֹחַ בַּ⁠חֲמִשָּׁ֤ה עָשָׂר֙ בּ֔⁠וֹ וְ⁠עָשֹׂ֣ה אֹת֔⁠וֹ י֖וֹם מִשְׁתֶּ֥ה וְ⁠שִׂמְחָֽה׃","whyhwdyym ʼàşěr-bĕ̇⁠ş̌ẇşá̌֗n niqĕhàlẇ֙ bi̇⁠şĕ̌lòşá֤̌h ʻáşá̂r֙ ḃ֔⁠wò ẇ⁠bĕ⁠ʼarĕbá̇ʻá֥h ʻáşá֖̂r ḃ֑⁠wò wĕ⁠n֗wòẖa bȧ⁠ẖàmişá֤̇̌h ʻáşá̂r֙ ḃ֔⁠wò wĕ⁠ʻáşò֣̂h ʼòţ֔⁠wò y֖wòm mişĕ̌ţė֥h wĕ⁠şîmĕẖáֽh׃"],[9,19,"עַל־כֵּ֞ן הַ⁠יְּהוּדִ֣ים ה⁠פרוזים הַ⁠יֹּשְׁבִים֮ בְּ⁠עָרֵ֣י הַ⁠פְּרָזוֹת֒ עֹשִׂ֗ים אֵ֠ת י֣וֹם אַרְבָּעָ֤ה עָשָׂר֙ לְ⁠חֹ֣דֶשׁ אֲדָ֔ר שִׂמְחָ֥ה וּ⁠מִשְׁתֶּ֖ה וְ⁠י֣וֹם ט֑וֹב וּ⁠מִשְׁל֥וֹחַ מָנ֖וֹת אִ֥ישׁ לְ⁠רֵעֵֽ⁠הוּ׃פ","ʻal-ké̇֞n ha⁠yĕ̇hẇdi֣ym h⁠prwzym ha⁠yò̇şĕ̌biym֮ bĕ̇⁠ʻáré֣y ha⁠pĕ̇rázwòţ֒ ʻòşî֗ym ʼé֠ţ y֣wòm ʼarĕbá̇ʻá֤h ʻáşá̂r֙ lĕ⁠ẖò֣deş̌ ʼàdá֔r şîmĕẖá֥h ẇ⁠mişĕ̌ţė֖h wĕ⁠y֣wòm t֑wòb ẇ⁠mişĕ̌l֥wòẖa mán֖wòţ ʼi֥yş̌ lĕ⁠réʻéֽ⁠hẇ׃p"],[9,20,"וַ⁠יִּכְתֹּ֣ב מָרְדֳּכַ֔י אֶת־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה וַ⁠יִּשְׁלַ֨ח סְפָרִ֜ים אֶל־כָּל־הַ⁠יְּהוּדִ֗ים אֲשֶׁר֙ בְּ⁠כָל־מְדִינוֹת֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ הַ⁠קְּרוֹבִ֖ים וְ⁠הָ⁠רְחוֹקִֽים׃","wa⁠yi̇kĕţò֣̇b márĕdȯka֔y ʼeţ-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh wa⁠yi̇şĕ̌la֨ẖ sĕpári֜ym ʼel-ká̇l-ha⁠yĕ̇hẇdi֗ym ʼàşěr֙ bĕ̇⁠kál-mĕdiynwòţ֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ ha⁠qĕ̇rwòbi֖ym wĕ⁠há⁠rĕẖwòqiֽym׃"],[9,21,"לְ⁠קַיֵּם֮ עֲלֵי⁠הֶם֒ לִ⁠הְי֣וֹת עֹשִׂ֗ים אֵ֠ת י֣וֹם אַרְבָּעָ֤ה עָשָׂר֙ לְ⁠חֹ֣דֶשׁ אֲדָ֔ר וְ⁠אֵ֛ת יוֹם־חֲמִשָּׁ֥ה עָשָׂ֖ר בּ֑⁠וֹ בְּ⁠כָל־שָׁנָ֖ה וְ⁠שָׁנָֽה׃","lĕ⁠qayé̇m֮ ʻàléy⁠hem֒ li⁠hĕy֣wòţ ʻòşî֗ym ʼé֠ţ y֣wòm ʼarĕbá̇ʻá֤h ʻáşá̂r֙ lĕ⁠ẖò֣deş̌ ʼàdá֔r wĕ⁠ʼé֛ţ ywòm-ẖàmişá֥̇̌h ʻáşá֖̂r ḃ֑⁠wò bĕ̇⁠kál-şá̌ná֖h wĕ⁠şá̌náֽh׃"],[9,22,"כַּ⁠יָּמִ֗ים אֲשֶׁר־נָ֨חוּ בָ⁠הֶ֤ם הַ⁠יְּהוּדִים֙ מֵ⁠א֣וֹיְבֵי⁠הֶ֔ם וְ⁠הַ⁠חֹ֗דֶשׁ אֲשֶׁר֩ נֶהְפַּ֨ךְ לָ⁠הֶ֤ם מִ⁠יָּגוֹן֙ לְ⁠שִׂמְחָ֔ה וּ⁠מֵ⁠אֵ֖בֶל לְ⁠י֣וֹם ט֑וֹב לַ⁠עֲשׂ֣וֹת אוֹתָ֗⁠ם יְמֵי֙ מִשְׁתֶּ֣ה וְ⁠שִׂמְחָ֔ה וּ⁠מִשְׁל֤וֹחַ מָנוֹת֙ אִ֣ישׁ לְ⁠רֵעֵ֔⁠הוּ וּ⁠מַתָּנ֖וֹת לָֽ⁠אֶבְיוֹנִֽים׃","kȧ⁠yá̇mi֗ym ʼàşěr-ná֨ẖẇ bá⁠he֤m ha⁠yĕ̇hẇdiym֙ mé⁠ʼ֣wòyĕbéy⁠he֔m wĕ⁠ha⁠ẖò֗deş̌ ʼàşěr֩ nehĕpȧ֨kĕ lá⁠he֤m mi⁠yá̇gwòn֙ lĕ⁠şîmĕẖá֔h ẇ⁠mé⁠ʼé֖bel lĕ⁠y֣wòm t֑wòb la⁠ʻàş֣̂wòţ ʼwòţá֗⁠m yĕméy֙ mişĕ̌ţė֣h wĕ⁠şîmĕẖá֔h ẇ⁠mişĕ̌l֤wòẖa mánwòţ֙ ʼi֣yş̌ lĕ⁠réʻé֔⁠hẇ ẇ⁠maţá̇n֖wòţ láֽ⁠ʼebĕywòniֽym׃"],[9,23,"וְ⁠קִבֵּל֙ הַ⁠יְּהוּדִ֔ים אֵ֥ת אֲשֶׁר־הֵחֵ֖לּוּ לַ⁠עֲשׂ֑וֹת וְ⁠אֵ֛ת אֲשֶׁר־כָּתַ֥ב מָרְדֳּכַ֖י אֲלֵי⁠הֶֽם׃","wĕ⁠qibé̇l֙ ha⁠yĕ̇hẇdi֔ym ʼé֥ţ ʼàşěr-héẖé֖l̇ẇ la⁠ʻàş֑̂wòţ wĕ⁠ʼé֛ţ ʼàşěr-ká̇ţa֥b márĕdȯka֖y ʼàléy⁠heֽm׃"],[9,24,"כִּי֩ הָמָ֨ן בֶּֽן־הַמְּדָ֜תָא הָֽ⁠אֲגָגִ֗י צֹרֵר֙ כָּל־הַ⁠יְּהוּדִ֔ים חָשַׁ֥ב עַל־הַ⁠יְּהוּדִ֖ים לְ⁠אַבְּדָ֑⁠ם וְ⁠הִפִּ֥יל פּוּר֙ ה֣וּא הַ⁠גּוֹרָ֔ל לְ⁠הֻמָּ֖⁠ם וּֽ⁠לְ⁠אַבְּדָֽ⁠ם׃","ki̇y֩ hámá֨n bėֽn-hamĕ̇dá֜ţáʼ háֽ⁠ʼàgági֗y ẕòrér֙ ká̇l-ha⁠yĕ̇hẇdi֔ym ẖáşǎ֥b ʻal-ha⁠yĕ̇hẇdi֖ym lĕ⁠ʼabĕ̇dá֑⁠m wĕ⁠hipi֥̇yl ṗẇr֙ h֣ẇʼ ha⁠ġwòrá֔l lĕ⁠humá֖̇⁠m ẇֽ⁠lĕ⁠ʼabĕ̇dáֽ⁠m׃"],[9,25,"וּ⁠בְ⁠בֹאָ⁠הּ֮ לִ⁠פְנֵ֣י הַ⁠מֶּלֶךְ֒ אָמַ֣ר עִם־הַ⁠סֵּ֔פֶר יָשׁ֞וּב מַחֲשַׁבְתּ֧⁠וֹ הָ⁠רָעָ֛ה אֲשֶׁר־חָשַׁ֥ב עַל־הַ⁠יְּהוּדִ֖ים עַל־רֹאשׁ֑⁠וֹ וְ⁠תָל֥וּ אֹת֛⁠וֹ וְ⁠אֶת־בָּנָ֖י⁠ו עַל־הָ⁠עֵֽץ׃","ẇ⁠bĕ⁠bòʼá⁠ḣ֮ li⁠pĕné֣y ha⁠mėlekĕ֒ ʼáma֣r ʻim-ha⁠sé̇֔per yáş̌֞ẇb maẖàşǎbĕţ֧̇⁠wò há⁠ráʻá֛h ʼàşěr-ẖáşǎ֥b ʻal-ha⁠yĕ̇hẇdi֖ym ʻal-ròʼş֑̌⁠wò wĕ⁠ţál֥ẇ ʼòţ֛⁠wò wĕ⁠ʼeţ-bá̇ná֖y⁠w ʻal-há⁠ʻéֽẕ׃"],[9,26,"עַל־כֵּ֡ן קָֽרְאוּ֩ לַ⁠יָּמִ֨ים הָ⁠אֵ֤לֶּה פוּרִים֙ עַל־שֵׁ֣ם הַ⁠פּ֔וּר עַל־כֵּ֕ן עַל־כָּל־דִּבְרֵ֖י הָ⁠אִגֶּ֣רֶת הַ⁠זֹּ֑את וּ⁠מָֽה־רָא֣וּ עַל־כָּ֔כָה וּ⁠מָ֥ה הִגִּ֖יעַ אֲלֵי⁠הֶֽם׃","ʻal-ké̇֡n qáֽrĕʼẇ֩ la⁠yá̇mi֨ym há⁠ʼé֤lėh pẇriym֙ ʻal-şé֣̌m ha⁠ṗ֔ẇr ʻal-ké̇֕n ʻal-ká̇l-di̇bĕré֖y há⁠ʼigė֣reţ ha⁠zò֑̇ʼţ ẇ⁠máֽh-ráʼ֣ẇ ʻal-ká̇֔káh ẇ⁠má֥h higi֖̇yʻa ʼàléy⁠heֽm׃"],[9,27,"קִיְּמ֣וּ ו⁠קבל הַ⁠יְּהוּדִים֩ ׀ עֲלֵי⁠הֶ֨ם ׀ וְ⁠עַל־זַרְעָ֜⁠ם וְ⁠עַ֨ל כָּל־הַ⁠נִּלְוִ֤ים עֲלֵי⁠הֶם֙ וְ⁠לֹ֣א יַעֲב֔וֹר לִ⁠הְי֣וֹת עֹשִׂ֗ים אֵ֣ת שְׁנֵ֤י הַ⁠יָּמִים֙ הָ⁠אֵ֔לֶּה כִּ⁠כְתָבָ֖⁠ם וְ⁠כִ⁠זְמַנָּ֑⁠ם בְּ⁠כָל־שָׁנָ֖ה וְ⁠שָׁנָֽה׃","qiyĕ̇m֣ẇ w⁠qbl ha⁠yĕ̇hẇdiym֩ ׀ ʻàléy⁠he֨m ׀ wĕ⁠ʻal-zarĕʻá֜⁠m wĕ⁠ʻa֨l ká̇l-ha⁠ni̇lĕwi֤ym ʻàléy⁠hem֙ wĕ⁠lò֣ʼ yaʻàb֔wòr li⁠hĕy֣wòţ ʻòşî֗ym ʼé֣ţ şĕ̌né֤y ha⁠yá̇miym֙ há⁠ʼé֔lėh ki̇⁠kĕţábá֖⁠m wĕ⁠ki⁠zĕmaná֑̇⁠m bĕ̇⁠kál-şá̌ná֖h wĕ⁠şá̌náֽh׃"],[9,28,"וְ⁠הַ⁠יָּמִ֣ים הָ֠⁠אֵלֶּה נִזְכָּרִ֨ים וְ⁠נַעֲשִׂ֜ים בְּ⁠כָל־דּ֣וֹר וָ⁠ד֗וֹר מִשְׁפָּחָה֙ וּ⁠מִשְׁפָּחָ֔ה מְדִינָ֥ה וּ⁠מְדִינָ֖ה וְ⁠עִ֣יר וָ⁠עִ֑יר וִ⁠ימֵ֞י הַ⁠פּוּרִ֣ים הָ⁠אֵ֗לֶּה לֹ֤א יַֽעַבְרוּ֙ מִ⁠תּ֣וֹךְ הַ⁠יְּהוּדִ֔ים וְ⁠זִכְרָ֖⁠ם לֹא־יָס֥וּף מִ⁠זַּרְעָֽ⁠ם׃ס","wĕ⁠ha⁠yá̇mi֣ym há֠⁠ʼélėh nizĕká̇ri֨ym wĕ⁠naʻàşî֜ym bĕ̇⁠kál-ḋ֣wòr wá⁠d֗wòr mişĕ̌pá̇ẖáh֙ ẇ⁠mişĕ̌pá̇ẖá֔h mĕdiyná֥h ẇ⁠mĕdiyná֖h wĕ⁠ʻi֣yr wá⁠ʻi֑yr wi⁠ymé֞y ha⁠ṗẇri֣ym há⁠ʼé֗lėh lò֤ʼ yaֽʻabĕrẇ֙ mi⁠ţ֣̇wòkĕ ha⁠yĕ̇hẇdi֔ym wĕ⁠zikĕrá֖⁠m lòʼ-yás֥ẇp mi⁠zȧrĕʻáֽ⁠m׃s"],[9,29,"וַ֠⁠תִּכְתֹּב אֶסְתֵּ֨ר הַ⁠מַּלְכָּ֧ה בַת־אֲבִיחַ֛יִל וּ⁠מָרְדֳּכַ֥י הַ⁠יְּהוּדִ֖י אֶת־כָּל־תֹּ֑קֶף לְ⁠קַיֵּ֗ם אֵ֣ת אִגֶּ֧רֶת הַ⁠פּוּרִ֛ים הַ⁠זֹּ֖את הַ⁠שֵּׁנִֽית׃","wa֠⁠ţi̇kĕţò̇b ʼesĕţé̇֨r ha⁠mȧlĕká֧̇h baţ-ʼàbiyẖa֛yil ẇ⁠márĕdȯka֥y ha⁠yĕ̇hẇdi֖y ʼeţ-ká̇l-ţò֑̇qep lĕ⁠qayé̇֗m ʼé֣ţ ʼigė֧reţ ha⁠ṗẇri֛ym ha⁠zò֖̇ʼţ ha⁠şé̇̌niֽyţ׃"],[9,30,"וַ⁠יִּשְׁלַ֨ח סְפָרִ֜ים אֶל־כָּל־הַ⁠יְּהוּדִ֗ים אֶל־שֶׁ֨בַע וְ⁠עֶשְׂרִ֤ים וּ⁠מֵאָה֙ מְדִינָ֔ה מַלְכ֖וּת אֲחַשְׁוֵר֑וֹשׁ דִּבְרֵ֥י שָׁל֖וֹם וֶ⁠אֱמֶֽת׃","wa⁠yi̇şĕ̌la֨ẖ sĕpári֜ym ʼel-ká̇l-ha⁠yĕ̇hẇdi֗ym ʼel-şě֨baʻ wĕ⁠ʻeşĕ̂ri֤ym ẇ⁠méʼáh֙ mĕdiyná֔h malĕk֖ẇţ ʼàẖaşĕ̌wér֑wòş̌ di̇bĕré֥y şá̌l֖wòm we⁠ʼèmeֽţ׃"],[9,31,"לְ⁠קַיֵּ֡ם אֵת־יְמֵי֩ הַ⁠פֻּרִ֨ים הָ⁠אֵ֜לֶּה בִּ⁠זְמַנֵּי⁠הֶ֗ם כַּ⁠אֲשֶׁר֩ קִיַּ֨ם עֲלֵי⁠הֶ֜ם מָרְדֳּכַ֤י הַ⁠יְּהוּדִי֙ וְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֔ה וְ⁠כַ⁠אֲשֶׁ֛ר קִיְּמ֥וּ עַל־נַפְשָׁ֖⁠ם וְ⁠עַל־זַרְעָ֑⁠ם דִּבְרֵ֥י הַ⁠צֹּמ֖וֹת וְ⁠זַעֲקָתָֽ⁠ם׃","lĕ⁠qayé̇֡m ʼéţ-yĕméy֩ ha⁠pu̇ri֨ym há⁠ʼé֜lėh bi̇⁠zĕmané̇y⁠he֗m kȧ⁠ʼàşěr֩ qiyȧ֨m ʻàléy⁠he֜m márĕdȯka֤y ha⁠yĕ̇hẇdiy֙ wĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֔h wĕ⁠ka⁠ʼàşě֛r qiyĕ̇m֥ẇ ʻal-napĕşá֖̌⁠m wĕ⁠ʻal-zarĕʻá֑⁠m di̇bĕré֥y ha⁠ẕò̇m֖wòţ wĕ⁠zaʻàqáţáֽ⁠m׃"],[9,32,"וּ⁠מַאֲמַ֣ר אֶסְתֵּ֔ר קִיַּ֕ם דִּבְרֵ֥י הַ⁠פֻּרִ֖ים הָ⁠אֵ֑לֶּה וְ⁠נִכְתָּ֖ב בַּ⁠סֵּֽפֶר׃פ","ẇ⁠maʼàma֣r ʼesĕţé̇֔r qiyȧ֕m di̇bĕré֥y ha⁠pu̇ri֖ym há⁠ʼé֑lėh wĕ⁠nikĕţá֖̇b bȧ⁠séֽ̇per׃p"],[10,1,"וַ⁠יָּשֶׂם֩ הַ⁠מֶּ֨לֶךְ אחשרש ׀ מַ֛ס עַל־הָ⁠אָ֖רֶץ וְ⁠אִיֵּ֥י הַ⁠יָּֽם׃","wa⁠yá̇şêm֩ ha⁠mė֨lekĕ ʼẖşrş ׀ ma֛s ʻal-há⁠ʼá֖reẕ wĕ⁠ʼiyé֥̇y ha⁠yáֽ̇m׃"],[10,2,"וְ⁠כָל־מַעֲשֵׂ֤ה תָקְפּ⁠וֹ֙ וּ⁠גְב֣וּרָת֔⁠וֹ וּ⁠פָרָשַׁת֙ גְּדֻלַּ֣ת מָרְדֳּכַ֔י אֲשֶׁ֥ר גִּדְּל֖⁠וֹ הַ⁠מֶּ֑לֶךְ הֲ⁠לוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֨פֶר֙ דִּבְרֵ֣י הַ⁠יָּמִ֔ים לְ⁠מַלְכֵ֖י מָדַ֥י וּ⁠פָרָֽס׃","wĕ⁠kál-maʻàşé֤̂h ţáqĕṗ⁠wò֙ ẇ⁠gĕb֣ẇráţ֔⁠wò ẇ⁠páráşǎţ֙ gĕ̇dulȧ֣ţ márĕdȯka֔y ʼàşě֥r gi̇dĕ̇l֖⁠wò ha⁠mė֑lekĕ hà⁠lwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֨per֙ di̇bĕré֣y ha⁠yá̇mi֔ym lĕ⁠malĕké֖y máda֥y ẇ⁠páráֽs׃"],[10,3,"כִּ֣י ׀ מָרְדֳּכַ֣י הַ⁠יְּהוּדִ֗י מִשְׁנֶה֙ לַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ וְ⁠גָדוֹל֙ לַ⁠יְּהוּדִ֔ים וְ⁠רָצ֖וּי לְ⁠רֹ֣ב אֶחָ֑י⁠ו דֹּרֵ֥שׁ טוֹב֙ לְ⁠עַמּ֔⁠וֹ וְ⁠דֹבֵ֥ר שָׁל֖וֹם לְ⁠כָל־זַרְעֽ⁠וֹ׃","ki֣̇y ׀ márĕdȯka֣y ha⁠yĕ̇hẇdi֗y mişĕ̌neh֙ la⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ wĕ⁠gádwòl֙ la⁠yĕ̇hẇdi֔ym wĕ⁠ráẕ֖ẇy lĕ⁠rò֣b ʼeẖá֑y⁠w dò̇ré֥ş̌ twòb֙ lĕ⁠ʻaṁ֔⁠wò wĕ⁠dòbé֥r şá̌l֖wòm lĕ⁠kál-zarĕʻֽ⁠wò׃"]]}};